final_template:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Root domain for the primary Route 53 hosted zone (non-secret default so apply runs unattended)."
  type        = string
  default     = "example.com"
}

locals {
  name            = "main"
  app_record_name = "app.${var.domain_name}"
}

# ---------------------------------------------------------------------------
# Networking foundation (greenfield - everything created here)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name}-public-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name}-public"
  }
}

resource "aws_route" "public_internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Application Load Balancer
# ---------------------------------------------------------------------------

resource "aws_security_group" "main" {
  name        = "main-alb-sg"
  description = "Ingress on HTTP/HTTPS only for the main application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound so the ALB can reach its targets"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = local.name
  }
}

resource "aws_lb" "main" {
  name                       = "main"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.main.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = local.name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_target_group" "main" {
  name        = "main"
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = local.name
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

# ---------------------------------------------------------------------------
# Route 53 - new hosted zone and ALB alias record
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "primary" {
  name = var.domain_name

  tags = {
    Name = "primary"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "main" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.app_record_name
  type    = "A"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "alb_dns_name" {
  description = "Public DNS name of the main application load balancer."
  value       = aws_lb.main.dns_name
}

output "record_fqdn" {
  description = "FQDN of the Route 53 alias record pointing at the load balancer."
  value       = aws_route53_record.main.fqdn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag applied consistently to all resources"
  type        = string
  default     = "dev"
}

locals {
  public_subnet_ids = [aws_subnet.public_0.id, aws_subnet.public_1.id]
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Network foundation (greenfield - all resources created in this configuration)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "my_application-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "my_application-igw"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_0" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name        = "my_application-public-0"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name        = "my_application-public-1"
    Environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "my_application-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public_0" {
  subnet_id      = aws_subnet.public_0.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role and instance profile for Elastic Beanstalk
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "eb_ec2_role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and environment
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "my_application" {
  name        = "my_application"
  description = "Basic Elastic Beanstalk application"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_environment" "app_env" {
  name                = "app-env"
  application         = aws_elastic_beanstalk_application.my_application.name
  tier                = "WebServer"
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.11"

  # EC2 instances assume eb_ec2_role via the instance profile
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  # VPC placement
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  # Auto Scaling bounds to control cost
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  tags = {
    Name        = "app-env"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "environment_endpoint" {
  description = "Public endpoint (CNAME) of the Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.app_env.cname
}

output "application_name" {
  description = "Name of the Elastic Beanstalk application"
  value       = aws_elastic_beanstalk_application.my_application.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Value of the Environment tag applied consistently to all resources."
  type        = string
  default     = "dev"
}

variable "solution_stack_name" {
  description = "Currently supported Elastic Beanstalk platform solution stack."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.4.0 running Python 3.11"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk environment hosts."
  type        = string
  default     = "t3.micro"
}

locals {
  app_name   = "myapp"
  bundle_key = "myapp/eb_app.zip"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Self-contained application source bundle
# ---------------------------------------------------------------------------

resource "local_file" "wsgi_app" {
  filename        = "${path.module}/eb_app/application.py"
  file_permission = "0644"
  content         = <<EOT
import os


def application(environ, start_response):
    status = "200 OK"
    body = os.environ.get("APP_MESSAGE", "Hello from Elastic Beanstalk!").encode("utf-8")

    response_headers = [
        ("Content-Type", "text/plain; charset=utf-8"),
        ("Content-Length", str(len(body))),
    ]

    start_response(status, response_headers)

    return [body]
EOT
}

data "archive_file" "eb_bundle" {
  type             = "zip"
  source_dir       = "${path.module}/eb_app"
  output_path      = "${path.module}/myapp_eb_bundle.zip"
  output_file_mode = "0644"

  depends_on = [local_file.wsgi_app]
}

# ---------------------------------------------------------------------------
# S3 bucket for application version source bundles
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"

  tags = merge(local.common_tags, {
    Name = "sampleapril26426"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_object" "examplebucket_object" {
  bucket       = aws_s3_bucket.sampleapril26426.id
  key          = local.bundle_key
  source       = data.archive_file.eb_bundle.output_path
  content_type = "application/zip"
  source_hash  = data.archive_file.eb_bundle.output_base64sha256

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# IAM: EC2 instance role for Beanstalk hosts
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name        = "eb_ec2_role"
  description = "EC2 instance role assumed by Elastic Beanstalk hosts."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# ---------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eb_service_role" {
  name        = "eb_service_role"
  description = "Service role assumed by Elastic Beanstalk for environment management."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# ---------------------------------------------------------------------------
# Networking prerequisites (greenfield: created here, never referenced by ID)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "myapp-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "myapp-public-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "myapp-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "myapp-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Elastic Beanstalk application, version, and environment
# ---------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "myapp" {
  name        = local.app_name
  description = "myapp Elastic Beanstalk application"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.myapp.name
  description = "myapp source bundle version"
  bucket      = aws_s3_bucket.sampleapril26426.id
  key         = aws_s3_object.examplebucket_object.key

  depends_on = [aws_s3_object.examplebucket_object]

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_environment" "myapp_env" {
  name                   = "myapp-env"
  application            = aws_elastic_beanstalk_application.myapp.name
  description            = "myapp web server environment"
  solution_stack_name    = var.solution_stack_name
  tier                   = "WebServer"
  version_label          = aws_elastic_beanstalk_application_version.version.name
  wait_for_ready_timeout = "30m"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  tags = merge(local.common_tags, {
    Name = "myapp-env"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "environment_url" {
  description = "Public URL of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.myapp_env.cname
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Static provider metadata (no infrastructure discovery)
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# User-controlled naming variables (safe defaults)
# -----------------------------------------------------------------------------
variable "application_name" {
  description = "Name of the Elastic Beanstalk application"
  type        = string
  default     = "eb-rds-app"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment"
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Project     = "eb-rds"
    Environment = var.environment_name
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking foundation
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-igw"
  })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-public-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 11)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-private-${count.index + 1}"
  })
}

# Public route table: only these subnets get 0.0.0.0/0 via the IGW
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table: local traffic only, no internet route
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Database subnet group (private subnets only)
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "default" {
  name       = "${var.environment_name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-db-subnet-group"
  })
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "eb_instances" {
  name        = "${var.environment_name}-eb-instances-sg"
  description = "Security group for Elastic Beanstalk EC2 instances (no ingress; egress allowed)"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-eb-instances-sg"
  })
}

resource "aws_security_group" "rds" {
  name        = "${var.environment_name}-rds-sg"
  description = "Security group for RDS PostgreSQL, reachable only from Beanstalk instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from Elastic Beanstalk EC2 instances only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instances.id]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-rds-sg"
  })
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role and instance profile
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# -----------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eb_service_role" {
  name = "eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "elasticbeanstalk.amazonaws.com",
            "cloudformation.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL (password managed by Secrets Manager, no plaintext credentials)
# -----------------------------------------------------------------------------
resource "aws_db_instance" "default" {
  identifier     = "${var.environment_name}-eb-rds-default"
  engine         = "postgres"
  engine_version = "15.5"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  max_allocated_storage = 100
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = "appdb"
  username = "dbadmin"

  # Master password is generated and rotated by RDS via Secrets Manager
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  multi_az            = false

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.environment_name}-eb-rds-default-final"

  copy_tags_to_snapshot = true

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-eb-rds-default"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Least-privilege read access to the RDS-managed master secret for the app
resource "aws_iam_role_policy" "eb_ec2_rds_secret_read" {
  name = "eb-ec2-rds-secret-read"
  role = aws_iam_role.eb_ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadRdsMasterSecret"
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_db_instance.default.master_user_secret[0].secret_arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and environment
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_application" "app" {
  name        = var.application_name
  description = "Elastic Beanstalk application backed by RDS PostgreSQL"

  tags = merge(local.common_tags, {
    Name = var.application_name
  })
}

resource "aws_elastic_beanstalk_environment" "env" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.0.0 running Python 3.11"
  tier                = "WebServer"

  tags = merge(local.common_tags, {
    Name = var.environment_name
  })

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "HealthReportingSystemType"
    value     = "enhanced"
  }

  # Database connection details passed to the application; these references
  # make the environment depend on the RDS instance.
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.default.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.default.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.default.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_SECRET_ARN"
    value     = aws_db_instance.default.master_user_secret[0].secret_arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_iam_role_policy.eb_ec2_rds_secret_read
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "beanstalk_environment_url" {
  description = "URL of the Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.env.endpoint_url
}

output "beanstalk_environment_cname" {
  description = "CNAME of the Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.env.cname
}

output "database_endpoint" {
  description = "Connection endpoint of the RDS PostgreSQL instance"
  value       = aws_db_instance.default.endpoint
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  project            = "web-app"
  environment        = "production"
  db_master_username = "webappadmin"
  db_name            = "webappdb"

  common_tags = {
    Environment = local.environment
    Project     = local.project
  }
}

# -----------------------------------------------------------------------------
# Networking: VPC, Internet Gateway, public subnets, and routing
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "web-app-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "web-app-igw"
  })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "web-app-public-subnet-1"
  })
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "web-app-public-subnet-2"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "web-app-public-route-table"
  })
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "app" {
  name        = "web-app-eb-instance-sg"
  description = "Elastic Beanstalk EC2 instances: HTTP/HTTPS from the internet, unrestricted egress"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (public web tier)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (public web tier)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Unrestricted egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "web-app-eb-instance-sg"
  })
}

resource "aws_security_group" "rds" {
  name        = "web-app-rds-sg"
  description = "RDS PostgreSQL: access restricted to the Elastic Beanstalk instances only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from the application security group only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  egress {
    description = "Unrestricted egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "web-app-rds-sg"
  })
}

# -----------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role and EC2 instance role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_service" {
  name = "web-app-eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowElasticBeanstalkToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "web-app-eb-service-role"
  })
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

resource "aws_iam_role" "eb_ec2" {
  name = "web-app-eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "web-app-eb-ec2-role"
  })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer" {
  role       = aws_iam_role.eb_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_role_policy" "eb_ec2_rds_secret" {
  name = "web-app-rds-secret-read"
  role = aws_iam_role.eb_ec2.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadRdsMasterCredentials"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = aws_secretsmanager_secret.rds.arn
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2" {
  name = "web-app-eb-ec2-profile"
  role = aws_iam_role.eb_ec2.name

  tags = merge(local.common_tags, {
    Name = "web-app-eb-ec2-profile"
  })
}

# -----------------------------------------------------------------------------
# RDS master credentials (no plaintext secrets in configuration)
# -----------------------------------------------------------------------------

resource "random_password" "rds_master" {
  length  = 32
  special = false
}

resource "random_string" "cname_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_secretsmanager_secret" "rds" {
  name                    = "web-app/rds/master-credentials"
  description             = "Master credentials for the web-app RDS PostgreSQL instance"
  recovery_window_in_days = 0

  tags = merge(local.common_tags, {
    Name = "web-app-rds-secret"
  })
}

resource "aws_secretsmanager_secret_version" "rds" {
  secret_id = aws_secretsmanager_secret.rds.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.rds_master.result
  })
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name       = "web-app-db-subnet-group"
  subnet_ids = [aws_subnet.public_1.id, aws_subnet.public_2.id]

  tags = merge(local.common_tags, {
    Name = "web-app-db-subnet-group"
  })
}

resource "aws_db_instance" "main" {
  identifier     = "web-app-db"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = local.db_name
  username = local.db_master_username
  password = random_password.rds_master.result
  port     = 5432

  db_subnet_group_name       = aws_db_subnet_group.main.name
  vpc_security_group_ids     = [aws_security_group.rds.id]
  parameter_group_name       = "default.postgres16"
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  publicly_accessible = false

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "web-app-db-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "web-app-db"
  })
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and environment
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "web" {
  name        = "web-app"
  description = "Web application deployed on AWS Elastic Beanstalk"

  tags = merge(local.common_tags, {
    Name = "web-app-eb-application"
  })
}

resource "aws_elastic_beanstalk_environment" "web" {
  name                = "web-app-env"
  application         = aws_elastic_beanstalk_application.web.name
  description         = "WebServer tier environment running Python 3.12 on Amazon Linux 2023"
  cname_prefix        = "web-app-env-${random_string.cname_suffix.result}"
  solution_stack_name = "64bit Amazon Linux 2023 v4.1.0 running Python 3.12"
  tier                = "WebServer"

  wait_for_ready_timeout = "45m"

  tags = merge(local.common_tags, {
    Name = "web-app-eb-environment"
  })

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.app.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceTypes"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.public_1.id, aws_subnet.public_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.public_1.id, aws_subnet.public_2.id])
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "ManagedActionsEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "PreferredStartTime"
    value     = "TUE:02:00"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "UpdateLevel"
    value     = "minor"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "InstanceRefreshEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.main.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.main.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.main.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_SECRET_ARN"
    value     = aws_secretsmanager_secret.rds.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer,
    aws_iam_role_policy.eb_ec2_rds_secret,
    aws_secretsmanager_secret_version.rds,
    aws_db_instance.main,
    aws_internet_gateway.main,
    aws_route_table.public,
    aws_route_table_association.public_1,
    aws_route_table_association.public_2,
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  zone_domain      = "host.example53.com"
  ptr_pointer_name = "1"
  ptr_target_fqdn  = "host.example53.com."
  environment      = "production"
}

# Public hosted zone used for reverse DNS pointers.
# A public zone is used (no vpc block) because this greenfield account
# has no pre-existing VPC to associate with a private zone.
resource "aws_route53_zone" "reverse_zone" {
  name = local.zone_domain

  comment = "Reverse DNS hosted zone for ${local.zone_domain}"

  tags = {
    Name        = "reverse_zone"
    Environment = local.environment
    Purpose     = "reverse-dns"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# PTR (pointer) record following reverse-DNS conventions:
# the pointer name is the host octet ("1") under the zone domain,
# mapping back to the canonical FQDN host.example53.com.
resource "aws_route53_record" "reverse_ptr" {
  zone_id = aws_route53_zone.reverse_zone.zone_id
  name    = "${local.ptr_pointer_name}.${aws_route53_zone.reverse_zone.name}"
  type    = "PTR"
  ttl     = 300
  records = [local.ptr_target_fqdn]
}

output "reverse_zone_id" {
  description = "The zone ID of the reverse DNS hosted zone."
  value       = aws_route53_zone.reverse_zone.zone_id
}

output "reverse_zone_name_servers" {
  description = "The name servers of the reverse DNS hosted zone, for downstream NS delegation."
  value       = aws_route53_zone.reverse_zone.name_servers
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "User-controlled public domain name used for the Route 53 hosted zone and failover records."
  type        = string
  default     = "example.com"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  db_username        = "myapp_admin"
  private_subnet_ids = [aws_subnet.private_az0.id, aws_subnet.private_az1.id]
  public_subnet_ids  = [aws_subnet.public_az0.id, aws_subnet.public_az1.id]
  app_record_name    = "app.${var.domain_name}"
}

# -----------------------------------------------------------------------------
# Database credentials (Secrets Manager)
# -----------------------------------------------------------------------------

resource "random_password" "db_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "random_id" "db_final_snapshot" {
  byte_length = 8
}

resource "aws_secretsmanager_secret" "myapp_db_credentials" {
  name        = "myapp_db_credentials"
  description = "Master credentials for the shared myapp_db RDS instance used by the blue and green environments."
}

resource "aws_secretsmanager_secret_version" "myapp_db_credentials" {
  secret_id = aws_secretsmanager_secret.myapp_db_credentials.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_password.result
    engine   = "postgres"
    port     = 5432
  })
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "myapp-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "myapp-igw"
  }
}

resource "aws_subnet" "public_az0" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "myapp-public-az0"
  }
}

resource "aws_subnet" "public_az1" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "myapp-public-az1"
  }
}

resource "aws_subnet" "private_az0" {
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[0]
  cidr_block        = "10.0.11.0/24"

  tags = {
    Name = "myapp-private-az0"
  }
}

resource "aws_subnet" "private_az1" {
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[1]
  cidr_block        = "10.0.12.0/24"

  tags = {
    Name = "myapp-private-az1"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "myapp-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_az0.id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "myapp-nat"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "myapp-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "myapp-private-rt"
  }
}

resource "aws_route_table_association" "public_az0" {
  subnet_id      = aws_subnet.public_az0.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_az1" {
  subnet_id      = aws_subnet.public_az1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private_az0" {
  subnet_id      = aws_subnet.private_az0.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_az1" {
  subnet_id      = aws_subnet.private_az1.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "app" {
  name        = "myapp-app-sg"
  description = "Ingress for the blue and green Elastic Beanstalk EC2 instances (HTTP/HTTPS only)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "myapp-app-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "myapp-rds-sg"
  description = "PostgreSQL access restricted to the application security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from app instances"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  tags = {
    Name = "myapp-rds-sg"
  }
}

# -----------------------------------------------------------------------------
# Shared RDS instance
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "myapp_db" {
  name       = "myapp_db"
  subnet_ids = local.private_subnet_ids

  tags = {
    Name = "myapp-db-subnet-group"
  }
}

resource "aws_db_instance" "myapp_db" {
  identifier     = "myapp-db"
  engine         = "postgres"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_encrypted     = true
  multi_az              = true
  publicly_accessible   = false

  username = jsondecode(aws_secretsmanager_secret_version.myapp_db_credentials.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.myapp_db_credentials.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.myapp_db.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "myapp-db-final-${random_id.db_final_snapshot.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "myapp_db"
  }
}

# -----------------------------------------------------------------------------
# IAM for Elastic Beanstalk EC2 instances
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = ""
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "eb_ec2_role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and blue/green environments
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "MyApp Elastic Beanstalk application hosting the blue and green environments"
}

resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "blue"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.12"
  tier                = "WebServer"
  cname_prefix        = "myapp-blue"
  wait_for_ready_timeout = "30m"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.private_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.app.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DATABASE_HOST"
    value     = aws_db_instance.myapp_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_SECRET_ARN"
    value     = aws_secretsmanager_secret.myapp_db_credentials.arn
  }

  depends_on = [
    aws_db_instance.myapp_db,
    aws_secretsmanager_secret_version.myapp_db_credentials,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
  ]
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = "green"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.12"
  tier                = "WebServer"
  cname_prefix        = "myapp-green"
  wait_for_ready_timeout = "30m"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.private_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.app.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DATABASE_HOST"
    value     = aws_db_instance.myapp_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_SECRET_ARN"
    value     = aws_secretsmanager_secret.myapp_db_credentials.arn
  }

  depends_on = [
    aws_db_instance.myapp_db,
    aws_secretsmanager_secret_version.myapp_db_credentials,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
  ]
}

# -----------------------------------------------------------------------------
# Route 53: hosted zone, health checks, and failover records
# -----------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = {
    Name = "myapp-zone"
  }
}

resource "aws_route53_health_check" "blue" {
  fqdn              = aws_elastic_beanstalk_environment.blue.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = {
    Name = "myapp-blue-health-check"
  }
}

resource "aws_route53_health_check" "green" {
  fqdn              = aws_elastic_beanstalk_environment.green.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = {
    Name = "myapp-green-health-check"
  }
}

resource "aws_route53_record" "myapp_primary" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.app_record_name
  type    = "CNAME"
  ttl     = 60

  set_identifier = "primary"

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.blue.id

  records = [aws_elastic_beanstalk_environment.blue.cname]
}

resource "aws_route53_record" "myapp_failover" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.app_record_name
  type    = "CNAME"
  ttl     = 60

  set_identifier = "secondary"

  failover_routing_policy {
    type = "SECONDARY"
  }

  health_check_id = aws_route53_health_check.green.id

  records = [aws_elastic_beanstalk_environment.green.cname]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "blue_environment_cname" {
  description = "CNAME of the blue Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.blue.cname
}

output "green_environment_cname" {
  description = "CNAME of the green Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.green.cname
}

output "route53_record_fqdn" {
  description = "FQDN of the failover-enabled Route 53 record serving production traffic."
  value       = aws_route53_record.myapp_primary.fqdn
}

output "rds_endpoint" {
  description = "Connection endpoint (host:port) of the shared RDS instance."
  value       = aws_db_instance.myapp_db.endpoint
}

output "rds_endpoint_address" {
  description = "Address of the shared RDS instance."
  value       = aws_db_instance.myapp_db.address
}

output "rds_endpoint_port" {
  description = "Port of the shared RDS instance."
  value       = aws_db_instance.myapp_db.port
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "app_image_identifier" {
  description = "User-controlled, non-infrastructure value: publicly accessible container image identifier deployed by App Runner (no external registry assets or account-specific IDs required)."
  type        = string
  default     = "public.ecr.aws/nginx/nginx:latest"
}

variable "tags" {
  description = "Consistent tags applied to every resource."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Secrets (no passwords, API keys, or credentials are hardcoded anywhere in
# this configuration; the runtime secret value is generated at apply time).
# ---------------------------------------------------------------------------

resource "random_password" "example" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "example" {
  name        = "web-app/example-secret"
  description = "Runtime secret for the App Runner web application."

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id     = aws_secretsmanager_secret.example.id
  secret_string = random_password.example.result
}

# ---------------------------------------------------------------------------
# IAM: explicit trust policy for apprunner.amazonaws.com, least-privilege
# permissions, bound with aws_iam_role_policy_attachment.
# ---------------------------------------------------------------------------

resource "aws_iam_role" "web_app_instance_role" {
  name = "web-app-apprunner-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apprunner.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "web_app_instance_policy" {
  name        = "web-app-apprunner-instance-policy"
  description = "Least-privilege runtime permissions for the App Runner web application instance role."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadAppSecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = [aws_secretsmanager_secret.example.arn]
      },
      {
        Sid    = "PublishXRayTraces"
        Effect = "Allow"
        Action = ["xray:PutTraceSegments", "xray:PutTelemetryRecords"]
        # X-Ray API actions do not support resource-level permissions;
        # Action is scoped to X-Ray write operations only (never "*" for both).
        Resource = ["*"]
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "web_app_instance_policy" {
  role       = aws_iam_role.web_app_instance_role.name
  policy_arn = aws_iam_policy.web_app_instance_policy.arn
}

# ---------------------------------------------------------------------------
# App Runner observability: W3C trace context propagation with AWS X-Ray.
# ---------------------------------------------------------------------------

resource "aws_apprunner_observability_configuration" "web_app_observability" {
  observability_configuration_name = "web-app-observability"

  trace_configuration {
    vendor = "AWSXRAY"
  }

  tags = var.tags
}

# ---------------------------------------------------------------------------
# App Runner service: deploys and scales the supported-language web
# application. Because no auto_scaling_configuration_arn is specified, App
# Runner automatically associates the latest revision of the platform default
# auto scaling configuration, which still provides concurrency-driven
# scale-out/in with a minimum of 1 instance — zero additional infrastructure.
#
# Networking (ingress, load balancing) and TLS termination are fully managed
# by App Runner — no security groups, load balancers, or ingress rules are
# created, and all traffic is served over HTTPS on the managed
# awsapprunner.com endpoint.
# ---------------------------------------------------------------------------

resource "aws_apprunner_service" "web_app" {
  service_name = "web-app"

  source_configuration {
    # ECR Public sources do not support App Runner auto deployments from the
    # registry; the App Runner platform performs deployment and rolling
    # updates whenever the service is created or updated (e.g. terraform apply).
    auto_deployments_enabled = false

    image_repository {
      image_identifier      = var.app_image_identifier
      image_repository_type = "ECR_PUBLIC"

      image_configuration {
        port = "80"

        # Map of environment variable name -> Secrets Manager secret ARN.
        # Only the ARN is referenced (never a secret value); App Runner
        # injects the decrypted value at runtime via the instance role's
        # secretsmanager:GetSecretValue permission.
        runtime_environment_secrets = {
          EXAMPLE_SECRET = aws_secretsmanager_secret.example.arn
        }
      }
    }
  }

  instance_configuration {
    instance_role_arn = aws_iam_role.web_app_instance_role.arn
  }

  health_check_configuration {
    path                = "/"
    protocol            = "HTTP"
    healthy_threshold   = 1
    unhealthy_threshold = 5
    interval            = 10
    timeout             = 5
  }

  observability_configuration {
    observability_enabled           = true
    observability_configuration_arn = aws_apprunner_observability_configuration.web_app_observability.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.web_app_instance_policy,
    aws_secretsmanager_secret_version.example,
  ]

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "service_url" {
  description = "HTTPS endpoint (App Runner managed TLS) of the deployed web application."
  value       = aws_apprunner_service.web_app.service_url
}

output "service_status" {
  description = "Current status of the App Runner service."
  value       = aws_apprunner_service.web_app.status
}

output "auto_scaling_configuration_arn" {
  description = "ARN of the auto scaling configuration associated with the web application (App Runner default configuration, providing concurrency-driven scaling with a minimum of 1 instance)."
  value       = aws_apprunner_service.web_app.auto_scaling_configuration_arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Pure local lookup of the current account ID, used only to guarantee a
# globally unique S3 bucket name in this greenfield account.
data "aws_caller_identity" "current" {}

variable "github_repo_url" {
  description = "HTTPS URL of the public GitHub repository that CodeBuild will build."
  type        = string
  default     = "https://github.com/example/hello-world.git"
}

variable "tags" {
  description = "Tags applied to all taggable resources for traceability."
  type        = map(string)
  default = {
    Environment = "example"
    Project     = "codebuild-example"
    ManagedBy   = "terraform"
  }
}

locals {
  project_name = "example-codebuild-project"
  cache_prefix = "cache"
}

# -----------------------------------------------------------------------------
# IAM role trusted exclusively by the CodeBuild service principal
# -----------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name        = "codebuild-example-service-role"
  description = "Service role trusted only by the AWS CodeBuild service principal."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codebuild.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

# -----------------------------------------------------------------------------
# Least-privilege inline policy: project log group + cache bucket prefix only
# -----------------------------------------------------------------------------
resource "aws_iam_role_policy" "codebuild" {
  name = "codebuild-least-privilege"
  role = aws_iam_role.codebuild.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild.arn,
          "${aws_cloudwatch_log_group.codebuild.arn}:*"
        ]
      },
      {
        Sid    = "CodeBuildS3Cache"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.codebuild_cache.arn}/${local.cache_prefix}/*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CloudWatch log group capturing build logs
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild" {
  name              = "/aws/codebuild/${local.project_name}"
  retention_in_days = 14
  tags              = var.tags
}

# -----------------------------------------------------------------------------
# S3 bucket backing the CodeBuild build cache
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "codebuild_cache" {
  bucket = "codebuild-example-cache-${data.aws_caller_identity.current.account_id}"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_cache" {
  bucket = aws_s3_bucket.codebuild_cache.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_cache" {
  bucket = aws_s3_bucket.codebuild_cache.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "codebuild_cache" {
  bucket = aws_s3_bucket.codebuild_cache.id

  rule {
    id     = "expire-cache-objects"
    status = "Enabled"

    filter {
      prefix = "${local.cache_prefix}/"
    }

    expiration {
      days = 30
    }
  }
}

# -----------------------------------------------------------------------------
# Secrets Manager secret backing the sensitive environment variable.
# The value is generated at apply time so that no plaintext secret ever
# appears in this configuration, in variable defaults, or in locals.
# -----------------------------------------------------------------------------
resource "random_password" "example" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "example" {
  name        = "codebuild/example/api-token"
  description = "Sensitive value injected into the CodeBuild build environment at runtime via a SECRETS_MANAGER environment variable."

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id     = aws_secretsmanager_secret.example.id
  secret_string = random_password.example.result
}

# -----------------------------------------------------------------------------
# CodeBuild project: GitHub source, environment variables, inline buildspec,
# and S3 cache. The default repository is a public example, so no
# aws_codebuild_source_credential resource is required; if you point
# var.github_repo_url at a private repository, add a source credential whose
# auth token is sourced from Secrets Manager.
# -----------------------------------------------------------------------------
resource "aws_codebuild_project" "example" {
  name         = local.project_name
  description  = "Example CodeBuild project with a GitHub source, environment variables, and an S3 build cache."
  service_role = aws_iam_role.codebuild.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  cache {
    type     = "S3"
    location = "${aws_s3_bucket.codebuild_cache.id}/${local.cache_prefix}"
  }

  environment {
    type                        = "LINUX_CONTAINER"
    image                       = "aws/codebuild/standard:7.0"
    compute_type                = "BUILD_GENERAL1_SMALL"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "APP_ENV"
      value = "example"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "LOG_LEVEL"
      value = "info"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "API_TOKEN"
      value = aws_secretsmanager_secret.example.arn
      type  = "SECRETS_MANAGER"
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild.name
    }
  }

  source {
    type            = "GITHUB"
    location        = var.github_repo_url
    git_clone_depth = 1

    buildspec = <<-EOT
      version: 0.2

      phases:
        install:
          commands:
            - echo "Install phase - no additional dependencies required for this example"
        pre_build:
          commands:
            - echo "Pre-build phase started on $(date)"
        build:
          commands:
            - echo "Build started on $(date)"
            - echo "APP_ENV=$APP_ENV"
            - echo "LOG_LEVEL=$LOG_LEVEL"
            - echo "Hello from CodeBuild!"
        post_build:
          commands:
            - echo "Build completed on $(date)"
    EOT
  }

  tags = var.tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to all taggable resources in this configuration."
  type        = map(string)
  default = {
    project     = "greenfield-codebuild-example"
    environment = "sandbox"
    managed_by  = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  project_name          = "greenfield_codebuild_example"
  artifacts_bucket_name = "greenfield-codebuild-example-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  log_group_name        = "/aws/codebuild/${local.project_name}"

  buildspec = <<-BUILDSPEC
    version: 0.2

    env:
      variables:
        BUILD_STAGE: "combine-secondary-sources"

    phases:
      pre_build:
        commands:
          - echo "Build started on $(date)"
          - echo "Primary source checkout: $CODEBUILD_SRC_DIR"
          - echo "Secondary source shared_libs checkout: $CODEBUILD_SRC_DIR_shared_libs"
          - echo "Secondary source public_docs checkout: $CODEBUILD_SRC_DIR_public_docs"
      build:
        commands:
          - echo "Combining primary source with both secondary sources"
          - mkdir -p "$CODEBUILD_SRC_DIR/secondary-output"
          - if [ -d "$CODEBUILD_SRC_DIR_shared_libs" ]; then cp -r "$CODEBUILD_SRC_DIR_shared_libs"/. "$CODEBUILD_SRC_DIR/"; fi
          - if [ -d "$CODEBUILD_SRC_DIR_public_docs" ]; then cp -r "$CODEBUILD_SRC_DIR_public_docs"/. "$CODEBUILD_SRC_DIR/secondary-output/"; fi
      post_build:
        commands:
          - echo "Build completed on $(date)"

    artifacts:
      files:
        - '**/*'

    secondary-artifacts:
      secondary_bundle:
        base-directory: secondary-output
        files:
          - '**/*'
  BUILDSPEC
}

resource "aws_kms_key" "codebuild" {
  description             = "KMS key for the ${local.project_name} CodeBuild project"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = var.tags
}

resource "aws_kms_key_policy" "codebuild" {
  key_id = aws_kms_key.codebuild.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootFullControl"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCodeBuildRoleUse"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.codebuild_role.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}*"
          }
        }
      },
    ]
  })
}

resource "aws_iam_role" "codebuild_role" {
  name = "${local.project_name}_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCodeBuildServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "codebuild_policy" {
  name        = "${local.project_name}_policy"
  description = "Least-privilege permissions for the CodeBuild project"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.codebuild_logs.name}",
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.codebuild_logs.name}:*",
        ]
      },
      {
        Sid    = "CodeBuildArtifactsObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
        ]
        Resource = "${aws_s3_bucket.artifacts.arn}/*"
      },
      {
        Sid    = "CodeBuildArtifactsBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
        ]
        Resource = aws_s3_bucket.artifacts.arn
      },
      {
        Sid    = "CodeBuildKmsAccess"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt",
        ]
        Resource = aws_kms_key.codebuild.arn
      },
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

resource "aws_s3_bucket" "artifacts" {
  bucket = local.artifacts_bucket_name

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.codebuild.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = local.log_group_name
  retention_in_days = 30
  kms_key_id        = aws_kms_key.codebuild.arn

  tags = var.tags

  depends_on = [aws_kms_key_policy.codebuild]
}

resource "aws_codebuild_project" "codebuild_project" {
  name           = local.project_name
  description    = "example_codebuild_project_with_secondary_sources"
  service_role   = aws_iam_role.codebuild_role.arn
  encryption_key = aws_kms_key.codebuild.arn
  build_timeout  = 15

  source {
    type      = "S3"
    location  = "${aws_s3_bucket.artifacts.bucket}/source.zip"
    buildspec = local.buildspec
  }

  secondary_sources {
    type              = "S3"
    source_identifier = "shared_libs"
    location          = "${aws_s3_bucket.artifacts.bucket}/secondary/shared-libs"
  }

  secondary_sources {
    type              = "GITHUB"
    source_identifier = "public_docs"
    location          = "https://github.com/hashicorp/go-cleanhttp.git"
  }

  artifacts {
    type      = "S3"
    location  = aws_s3_bucket.artifacts.bucket
    name      = "combined-build-output"
    packaging = "ZIP"
  }

  secondary_artifacts {
    artifact_identifier = "secondary_bundle"
    type                = "S3"
    location            = aws_s3_bucket.artifacts.bucket
    name                = "secondary-bundle-output"
    packaging           = "ZIP"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode             = false
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
    }
  }

  tags = var.tags

  depends_on = [aws_iam_role_policy_attachment.codebuild_policy_attachment]
}

output "codebuild_project_name" {
  description = "Name of the CodeBuild project."
  value       = aws_codebuild_project.codebuild_project.name
}

output "codebuild_project_arn" {
  description = "ARN of the CodeBuild project."
  value       = aws_codebuild_project.codebuild_project.arn
}

output "codebuild_role_arn" {
  description = "ARN of the CodeBuild IAM service role."
  value       = aws_iam_role.codebuild_role.arn
}

output "artifacts_bucket_arn" {
  description = "ARN of the S3 artifacts bucket."
  value       = aws_s3_bucket.artifacts.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all taggable resources"
  type        = string
  default     = "dev"
}

locals {
  tags = {
    Environment = var.environment
    Application = "greeting-lex-bot"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# IAM: execution role assumed by the Amazon Lex V2 service
# ------------------------------------------------------------------------------
resource "aws_iam_role" "lex_bot" {
  name        = "greeting-lex-bot-role"
  description = "Execution role assumed by lexv2.amazonaws.com for the greeting bot"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLexV2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

# Least-privilege inline policy: the bot only needs Polly to synthesize voice replies
resource "aws_iam_role_policy" "lex_bot_polly" {
  name = "greeting-lex-bot-polly-synthesize"
  role = aws_iam_role.lex_bot.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowPollySynthesizeSpeech"
        Effect   = "Allow"
        Action   = ["polly:SynthesizeSpeech"]
        Resource = ["*"]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Amazon Lex V2 bot
# ------------------------------------------------------------------------------
resource "aws_lexv2models_bot" "lex_bot" {
  name                        = "greeting_bot"
  description                 = "Amazon Lex V2 bot that greets users and captures their name"
  role_arn                    = aws_iam_role.lex_bot.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = false
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Built en_US DRAFT locale with an Amazon Polly voice
resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                           = aws_lexv2models_bot.lex_bot.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  description                      = "English (United States) locale"
  n_lu_intent_confidence_threshold = 0.70

  voice_settings {
    voice_id = "Joanna"
  }
}

# ------------------------------------------------------------------------------
# Custom slot type used by the greeting intent
# ------------------------------------------------------------------------------
resource "aws_lexv2models_slot_type" "user_name_type" {
  name        = "UserNameType"
  description = "Closed-list custom slot type used to capture the user's name"
  bot_id      = aws_lexv2models_bot.lex_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id

  slot_type_values {
    sample_value {
      value = "Alex"
    }
  }

  slot_type_values {
    sample_value {
      value = "Jordan"
    }
  }

  slot_type_values {
    sample_value {
      value = "Taylor"
    }
  }

  value_selection_setting {
    resolution_strategy = "OriginalValue"
  }
}

# ------------------------------------------------------------------------------
# Greeting intent
# ------------------------------------------------------------------------------
resource "aws_lexv2models_intent" "greeting" {
  name        = "GreetingIntent"
  description = "Greets the user, elicits their name, and closes the conversation"
  bot_id      = aws_lexv2models_bot.lex_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id

  sample_utterance {
    utterance = "Hello"
  }

  sample_utterance {
    utterance = "Hi"
  }

  sample_utterance {
    utterance = "Good morning"
  }

  initial_response_setting {
    initial_response {
      message_group {
        message {
          plain_text_message {
            value = "Hello! I am your friendly greeting assistant."
          }
        }
      }
    }
  }

  closing_setting {
    active = true

    closing_response {
      message_group {
        message {
          plain_text_message {
            value = "Thanks for chatting with me. Goodbye!"
          }
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Slot attached to the greeting intent to capture user input
# ------------------------------------------------------------------------------
resource "aws_lexv2models_slot" "user_name" {
  name         = "UserName"
  description  = "Captures the name of the user during the greeting flow"
  bot_id       = aws_lexv2models_bot.lex_bot.id
  bot_version  = "DRAFT"
  intent_id    = aws_lexv2models_intent.greeting.intent_id
  locale_id    = aws_lexv2models_bot_locale.en_us.locale_id
  slot_type_id = aws_lexv2models_slot_type.user_name_type.slot_type_id

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      allow_interrupt            = true
      max_retries                = 2
      message_selection_strategy = "Random"

      message_group {
        message {
          plain_text_message {
            value = "What is your name?"
          }
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Immutable numbered version created from the built DRAFT locale
# ------------------------------------------------------------------------------
resource "aws_lexv2models_bot_version" "initial" {
  bot_id      = aws_lexv2models_bot.lex_bot.id
  description = "Initial immutable version of the greeting bot"

  locale_specification = {
    "en_US" = {
      source_bot_version = "DRAFT"
    }
  }

  depends_on = [
    aws_lexv2models_bot_locale.en_us,
    aws_lexv2models_slot_type.user_name_type,
    aws_lexv2models_intent.greeting,
    aws_lexv2models_slot.user_name,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_intent" "book_trip" {
  name        = "BookTrip"
  description = "Intent for booking a trip"

  sample_utterances = [
    "Book a trip to {PickupCity} on {PickupDate}",
    "Book a trip from {PickupCity} to {ReturnCity}",
    "Schedule a trip for {PickupDate}",
    "I would like to book a trip from {PickupCity} to {ReturnCity} on {PickupDate}",
    "Book a trip with a driver age of {DriverAge}",
  ]

  confirmation_prompt {
    max_attempts = 1

    message {
      content_type = "PlainText"
      content      = "Just to confirm: a trip with pickup in {PickupCity} on {PickupDate}, drop-off in {ReturnCity}, and a driver age of {DriverAge}. Shall I book it?"
    }
  }

  rejection_statement {
    message {
      content_type = "PlainText"
      content      = "Okay, I will not book the trip. Let me know whenever you would like to try again."
    }
  }

  conclusion_statement {
    message {
      content_type = "PlainText"
      content      = "Your trip booking has been recorded. Thank you and have a great journey!"
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }

  slot {
    name              = "PickupCity"
    description       = "The city where the traveler will be picked up"
    priority          = 1
    slot_constraint   = "Required"
    slot_type         = "AMAZON.City"
    slot_type_version = "1"
    sample_utterances = ["Seattle"]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content_type = "PlainText"
        content      = "In which city would you like to be picked up?"
      }
    }
  }

  slot {
    name              = "PickupDate"
    description       = "The date on which the trip starts"
    priority          = 2
    slot_constraint   = "Required"
    slot_type         = "AMAZON.Date"
    slot_type_version = "1"
    sample_utterances = ["tomorrow"]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content_type = "PlainText"
        content      = "On which date would you like to start your trip?"
      }
    }
  }

  slot {
    name              = "ReturnCity"
    description       = "The destination city where the trip ends"
    priority          = 3
    slot_constraint   = "Required"
    slot_type         = "AMAZON.City"
    slot_type_version = "1"
    sample_utterances = ["Portland"]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content_type = "PlainText"
        content      = "In which city would you like your trip to end?"
      }
    }
  }

  slot {
    name              = "DriverAge"
    description       = "The age of the driver for the trip"
    priority          = 4
    slot_constraint   = "Required"
    slot_type         = "AMAZON.Number"
    slot_type_version = "1"
    sample_utterances = ["30"]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content_type = "PlainText"
        content      = "What is the age of the driver for this trip?"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_bot" "trip_booking_bot" {
  name        = "TripBookingBot"
  description = "Bot for booking trips"

  locale                          = "en-US"
  child_directed                  = false
  process_behavior                = "BUILD"
  create_version                  = true
  detect_sentiment                = true
  idle_session_ttl_in_seconds     = 300
  voice_id                        = "Joanna"
  enable_model_improvements       = true
  nlu_intent_confidence_threshold = 0.6

  intent {
    intent_name    = aws_lex_intent.book_trip.name
    intent_version = "$LATEST"
  }

  abort_statement {
    message {
      content_type = "PlainText"
      content      = "Sorry, I am unable to book your trip at this time. Please try again later."
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content_type = "PlainText"
      content      = "Sorry, I did not understand that. Could you please rephrase your trip booking request?"
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "bot_name" {
  description = "Name of the Lex trip booking bot"
  value       = aws_lex_bot.trip_booking_bot.name
}

output "bot_arn" {
  description = "ARN of the Lex trip booking bot"
  value       = aws_lex_bot.trip_booking_bot.arn
}

output "bot_status" {
  description = "Build status of the Lex trip booking bot"
  value       = aws_lex_bot.trip_booking_bot.status
}

output "bot_version" {
  description = "Published version of the Lex trip booking bot"
  value       = aws_lex_bot.trip_booking_bot.version
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  lex_service_principal = "lex.amazonaws.com"

  common_tags = {
    Project   = "pizza-ordering"
    Component = "lex-pizza-bot"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Service-linked role so Amazon Lex can call Polly/Comprehend on the bot's
# behalf in this greenfield account.
# -----------------------------------------------------------------------------
resource "aws_iam_service_linked_role" "lex" {
  aws_service_name = "lex.amazonaws.com"
  description      = "Service-linked role for the pizza ordering Amazon Lex bot"
}

# -----------------------------------------------------------------------------
# Lambda execution role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "lambda_exec" {
  name        = "pizza-fulfillment-lambda-exec"
  description = "Execution role for the pizza fulfillment Lambda function"
  tags        = local.common_tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_exec_basic" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# -----------------------------------------------------------------------------
# Inline fulfillment handler packaged for Lambda deployment
# -----------------------------------------------------------------------------
data "archive_file" "pizza_fulfillment_zip" {
  type        = "zip"
  output_path = "${path.module}/pizza_fulfillment_lambda.zip"

  source {
    filename = "index.py"
    content  = <<-PY
import json
import logging
import uuid

LOGGER = logging.getLogger()
LOGGER.setLevel(logging.INFO)

VALID_SIZES = ("small", "medium", "large")
VALID_CRUSTS = ("thin", "thick")
VALID_TOPPINGS = ("pepperoni", "mushroom", "sausage", "onion", "olives", "bacon")
MIN_QUANTITY = 1
MAX_QUANTITY = 20


def elicit_slot(session_attributes, intent_name, slots, slot_to_elicit, message):
    return {
        "sessionAttributes": session_attributes,
        "dialogAction": {
            "type": "ElicitSlot",
            "intentName": intent_name,
            "slots": slots,
            "slotToElicit": slot_to_elicit,
            "message": {"contentType": "PlainText", "content": message},
        },
    }


def close(session_attributes, fulfillment_state, message):
    return {
        "sessionAttributes": session_attributes,
        "dialogAction": {
            "type": "Close",
            "fulfillmentState": fulfillment_state,
            "message": {"contentType": "PlainText", "content": message},
        },
    }


def normalize(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def parse_quantity(value):
    try:
        number = int(str(value).strip())
    except (TypeError, ValueError):
        return None
    if number < MIN_QUANTITY or number > MAX_QUANTITY:
        return None
    return number


def handler(event, context):
    LOGGER.info("Received event: %s", json.dumps(event))

    intent_name = event["currentIntent"]["name"]
    slots = dict(event["currentIntent"].get("slots") or {})
    session_attributes = dict(event.get("sessionAttributes") or {})

    pizza_size = normalize(slots.get("pizza_size"))
    pizza_crust = normalize(slots.get("pizza_crust"))
    pizza_toppings = normalize(slots.get("pizza_toppings"))
    quantity = parse_quantity(slots.get("quantity"))

    if pizza_size and pizza_size not in VALID_SIZES:
        slots["pizza_size"] = None
        return elicit_slot(
            session_attributes,
            intent_name,
            slots,
            "pizza_size",
            "What size pizza would you like - small, medium, or large?",
        )

    if pizza_crust and pizza_crust not in VALID_CRUSTS:
        slots["pizza_crust"] = None
        return elicit_slot(
            session_attributes,
            intent_name,
            slots,
            "pizza_crust",
            "What kind of crust would you like - thin or thick?",
        )

    if pizza_toppings and pizza_toppings not in VALID_TOPPINGS:
        slots["pizza_toppings"] = None
        return elicit_slot(
            session_attributes,
            intent_name,
            slots,
            "pizza_toppings",
            "Which topping would you like - pepperoni, mushroom, sausage, onion, olives, or bacon?",
        )

    if quantity is None:
        slots["quantity"] = None
        return elicit_slot(
            session_attributes,
            intent_name,
            slots,
            "quantity",
            "How many pizzas would you like? Please give me a number between 1 and 20.",
        )

    slots["pizza_size"] = pizza_size
    slots["pizza_crust"] = pizza_crust
    slots["pizza_toppings"] = pizza_toppings
    slots["quantity"] = str(quantity)

    order_id = str(uuid.uuid4())
    session_attributes["orderId"] = order_id

    summary = (
        "Order {order_id} confirmed: {quantity} {size} pizza with {crust} crust "
        "and {toppings} toppings. Your pizza is on the way!"
    ).format(
        order_id=order_id,
        quantity=quantity,
        size=pizza_size,
        crust=pizza_crust,
        toppings=pizza_toppings,
    )

    LOGGER.info("Fulfilled pizza order %s", order_id)
    return close(session_attributes, "Fulfilled", summary)
PY
  }
}

# -----------------------------------------------------------------------------
# Lambda function, logs, and Lex invocation permission
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "pizza_fulfillment_logs" {
  name              = "/aws/lambda/${aws_lambda_function.pizza_fulfillment.function_name}"
  retention_in_days = 14
  tags              = local.common_tags
}

resource "aws_lambda_function" "pizza_fulfillment" {
  function_name = "pizza-fulfillment"
  description   = "Validates and fulfills pizza orders collected by the pizza ordering Lex bot"
  role          = aws_iam_role.lambda_exec.arn
  handler       = "index.handler"
  runtime       = "python3.12"
  memory_size   = 256
  timeout       = 10

  filename         = data.archive_file.pizza_fulfillment_zip.output_path
  source_code_hash = data.archive_file.pizza_fulfillment_zip.output_base64sha256

  tags = local.common_tags

  depends_on = [aws_iam_role_policy_attachment.lambda_exec_basic]
}

resource "aws_lambda_permission" "lex_invoke" {
  statement_id  = "AllowLexInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.pizza_fulfillment.function_name
  principal     = local.lex_service_principal
  source_arn    = aws_lex_bot.pizza_order_bot.arn
}

# -----------------------------------------------------------------------------
# Lex custom slot types (pizza domain vocabulary)
# -----------------------------------------------------------------------------
resource "aws_lex_slot_type" "pizza_size_type" {
  name           = "PizzaSizeType"
  description    = "Valid pizza sizes"
  create_version = true

  enumeration_value {
    value = "small"
  }

  enumeration_value {
    value = "medium"
  }

  enumeration_value {
    value = "large"
  }
}

resource "aws_lex_slot_type" "pizza_crust_type" {
  name           = "PizzaCrustType"
  description    = "Valid pizza crust styles"
  create_version = true

  enumeration_value {
    value = "thin"
  }

  enumeration_value {
    value = "thick"
  }
}

resource "aws_lex_slot_type" "pizza_toppings_type" {
  name           = "PizzaToppingsType"
  description    = "Valid pizza toppings"
  create_version = true

  enumeration_value {
    value = "pepperoni"
  }

  enumeration_value {
    value = "mushroom"
  }

  enumeration_value {
    value = "sausage"
  }

  enumeration_value {
    value = "onion"
  }

  enumeration_value {
    value = "olives"
  }

  enumeration_value {
    value = "bacon"
  }
}

# -----------------------------------------------------------------------------
# Lex intent for ordering a pizza, fulfilled by Lambda
# -----------------------------------------------------------------------------
resource "aws_lex_intent" "order_pizza" {
  name           = "order_pizza"
  description    = "Collects a pizza order (size, crust, toppings, quantity) and fulfills it with Lambda"
  create_version = true

  sample_utterances = [
    "I would like to order a {pizza_size} pizza",
    "I want to order {quantity} {pizza_size} pizzas",
    "Order a {pizza_size} {pizza_crust} pizza with {pizza_toppings}",
    "I would like a {pizza_size} pizza with {pizza_crust} crust",
    "Please order me a {pizza_size} pizza",
    "Order pizza",
  ]

  slot {
    name              = "pizza_size"
    description       = "Size of the pizza"
    slot_constraint   = "Required"
    slot_type         = aws_lex_slot_type.pizza_size_type.name
    slot_type_version = aws_lex_slot_type.pizza_size_type.version
    priority          = 1

    sample_utterances = [
      "I would like a {pizza_size} pizza",
      "Make it a {pizza_size} pizza",
    ]

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What size pizza would you like - small, medium, or large?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name              = "pizza_crust"
    description       = "Style of the pizza crust"
    slot_constraint   = "Required"
    slot_type         = aws_lex_slot_type.pizza_crust_type.name
    slot_type_version = aws_lex_slot_type.pizza_crust_type.version
    priority          = 2

    sample_utterances = [
      "I would like a {pizza_size} pizza with {pizza_crust} crust",
    ]

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What kind of crust would you like - thin or thick?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name              = "pizza_toppings"
    description       = "Topping for the pizza"
    slot_constraint   = "Required"
    slot_type         = aws_lex_slot_type.pizza_toppings_type.name
    slot_type_version = aws_lex_slot_type.pizza_toppings_type.version
    priority          = 3

    sample_utterances = [
      "I would like a {pizza_size} pizza with {pizza_toppings}",
    ]

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "Which topping would you like - pepperoni, mushroom, sausage, onion, olives, or bacon?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name            = "quantity"
    description     = "Number of pizzas to order"
    slot_constraint = "Required"
    slot_type       = "AMAZON.Number"
    priority        = 4

    sample_utterances = [
      "I would like {quantity} pizzas",
    ]

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "How many pizzas would you like?"
        content_type = "PlainText"
      }
    }
  }

  fulfillment_activity {
    type = "CodeHook"

    code_hook {
      uri             = aws_lambda_function.pizza_fulfillment.arn
      message_version = "1"
    }
  }
}

# -----------------------------------------------------------------------------
# Lex bot and stable production alias
# -----------------------------------------------------------------------------
resource "aws_lex_bot" "pizza_order_bot" {
  name                          = "PizzaOrderBot"
  description                   = "Takes pizza orders and fulfills them with Lambda"
  locale                        = "en-US"
  process_behavior              = "BUILD"
  child_directed                = false
  voice_id                      = "Joanna"
  create_version                = true
  enable_model_improvements     = true
  nlu_intent_confidence_threshold = 0.75
  idle_session_ttl_in_seconds   = 300

  intent {
    intent_name    = aws_lex_intent.order_pizza.name
    intent_version = aws_lex_intent.order_pizza.version
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "Sorry, I did not catch that. Could you please repeat your pizza order?"
      content_type = "PlainText"
    }
  }

  abort_statement {
    message {
      content      = "Sorry, I could not process your pizza order. Please try again later."
      content_type = "PlainText"
    }
  }

  depends_on = [aws_iam_service_linked_role.lex]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_bot_alias" "pizza_bot_prod" {
  bot_name    = aws_lex_bot.pizza_order_bot.name
  bot_version = aws_lex_bot.pizza_order_bot.version
  name        = "pizza_bot_prod"
  description = "Production alias for the pizza ordering Lex bot"
}

