}

output "pizza_bot_arn" {
  description = "ARN of the pizza ordering Lex bot"
  value       = aws_lex_bot.pizza_order_bot.arn
}

output "pizza_bot_version" {
  description = "Published version of the pizza ordering Lex bot"
  value       = aws_lex_bot.pizza_order_bot.version
}

output "pizza_bot_alias_name" {
  description = "Name of the production alias for the pizza ordering Lex bot"
  value       = aws_lex_bot_alias.pizza_bot_prod.name
}

output "pizza_bot_alias_arn" {
  description = "ARN of the production alias for the pizza ordering Lex bot"
  value       = aws_lex_bot_alias.pizza_bot_prod.arn
}

output "pizza_fulfillment_lambda_name" {
  description = "Name of the pizza fulfillment Lambda function"
  value       = aws_lambda_function.pizza_fulfillment.function_name
}

output "pizza_fulfillment_lambda_arn" {
  description = "ARN of the pizza fulfillment Lambda function"
  value       = aws_lambda_function.pizza_fulfillment.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Deployment environment name for the kids assistant stack (non-sensitive)."
  type        = string
  default     = "dev"
}

# Amazon Connect instance for the kids telephony experience.
resource "aws_connect_instance" "kids_connect" {
  instance_alias           = "kids-connect"
  identity_management_type = "CONNECT_MANAGED"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true

  lifecycle {
    prevent_destroy = true
  }
}

# Kid-friendly greeting intent, fulfilled without any Lambda hook.
resource "aws_lex_intent" "kids_greeting" {
  name        = "KidsGreeting"
  description = "Friendly greeting intent for the kids assistant bot"

  sample_utterances = [
    "hello",
    "hi",
    "hey there",
    "good morning",
    "can you help me",
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Kid-friendly Lex bot, COPPA-compliant via child_directed.
resource "aws_lex_bot" "kids_assistant" {
  name                      = "kids_assistant_bot"
  description               = "Kid-friendly assistant bot for the ${var.environment} environment"
  child_directed            = true
  enable_model_improvements = true
  locale                    = "en-US"
  process_behavior          = "BUILD"

  abort_statement {
    message {
      content      = "Sorry, I did not understand that. Goodbye for now, friend!"
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "Hmm, I did not quite catch that. Can you say it one more time?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.kids_greeting.name
    intent_version = "$LATEST"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Associate the kid-friendly Lex bot with the kids Connect instance.
resource "aws_connect_bot_association" "kids_bot" {
  instance_id = aws_connect_instance.kids_connect.id

  lex_bot {
    name       = aws_lex_bot.kids_assistant.name
    lex_region = "us-east-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "connect_instance_id" {
  description = "The ID of the Amazon Connect instance."
  value       = aws_connect_instance.kids_connect.id
}

output "connect_instance_alias" {
  description = "The alias of the Amazon Connect instance."
  value       = aws_connect_instance.kids_connect.instance_alias
}

output "lex_bot_name" {
  description = "The name of the kid-friendly Lex bot associated with the Connect instance."
  value       = aws_lex_bot.kids_assistant.name
}

###############################################################################
# Terraform setup
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Static provider metadata lookups (no dependency on pre-existing infrastructure)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Variables (non-infrastructure values only, all defaulted for unattended apply)
###############################################################################

variable "application_name_suffix" {
  description = "Suffix used when constructing the application and resource names"
  type        = string
  default     = "flink-app"
}

variable "environment" {
  description = "Environment classification applied as a tag to every resource"
  type        = string
  default     = "dev"
}

variable "log_retention_days" {
  description = "CloudWatch Logs retention period (in days) for the application log group"
  type        = number
  default     = 14

  validation {
    condition = contains(
      [1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653],
      var.log_retention_days
    )
    error_message = "log_retention_days must be a value accepted by CloudWatch Logs (e.g. 1, 3, 5, 7, 14, 30, 365)."
  }
}

variable "flink_parallelism" {
  description = "Initial parallelism for the Flink application"
  type        = number
  default     = 1
}

variable "flink_parallelism_per_kpu" {
  description = "Flink parallelism per Kinesis Processing Unit (KPU)"
  type        = number
  default     = 1
}

variable "flink_application_properties" {
  description = "Runtime configuration properties passed to the Flink application"
  type        = map(string)
  default = {
    INPUT_STREAM_NAME     = "example-input-stream"
    OUTPUT_STREAM_NAME    = "example-output-stream"
    AGGREGATION_WINDOW_MS = "1000"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  application_name = "kda-${var.application_name_suffix}-${var.environment}"

  aws_region = data.aws_region.current.name

  code_bucket_name = "kda-${var.application_name_suffix}-${var.environment}-code-${data.aws_caller_identity.current.account_id}"

  # Constructed from static provider metadata (avoids a dependency cycle with
  # the log group resource, which consumes this KMS key). Log group ARNs as
  # reported by AWS carry a trailing ":*", so the wildcard pattern below
  # matches both forms under ArnLike.
  flink_log_group_arn_pattern = "arn:${data.aws_partition.current.partition}:logs:${local.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/kinesisanalytics/${local.application_name}:*"

  common_tags = {
    Application = local.application_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# S3 code bucket hosting the Apache Flink application JAR
###############################################################################

resource "aws_s3_bucket" "code" {
  bucket = local.code_bucket_name

  tags = merge(local.common_tags, {
    Name = local.code_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "code" {
  bucket = aws_s3_bucket.code.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "code" {
  bucket = aws_s3_bucket.code.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "code" {
  bucket = aws_s3_bucket.code.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.flink_app.arn
    }
  }
}

resource "aws_s3_bucket_policy" "code" {
  bucket = aws_s3_bucket.code.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.code.arn,
          "${aws_s3_bucket.code.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.code]
}

resource "aws_s3_object" "flink_code" {
  bucket = aws_s3_bucket.code.id
  key    = "flink-app/code.jar"

  content      = "placeholder-flink-application-jar"
  content_type = "application/java-archive"

  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.flink_app.arn

  tags = merge(local.common_tags, {
    Name = "${local.application_name}-code-artifact"
  })

  depends_on = [
    aws_s3_bucket_versioning.code,
    aws_s3_bucket_server_side_encryption_configuration.code,
  ]
}

###############################################################################
# Customer-managed KMS key enforcing at-rest encryption
###############################################################################

resource "aws_kms_key" "flink_app" {
  description             = "Customer-managed key encrypting the ${local.application_name} Flink application"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowFlinkServiceExecutionRoleApplicationEncryption"
        Effect    = "Allow"
        Principal = {
          AWS = aws_iam_role.flink_app_exec.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowCloudWatchLogsLogGroupEncryption"
        Effect    = "Allow"
        Principal = {
          Service = "logs.${local.aws_region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.flink_log_group_arn_pattern
          }
        }
      },
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "flink_app" {
  name          = "alias/${local.application_name}"
  target_key_id = aws_kms_key.flink_app.key_id
}

###############################################################################
# CloudWatch Logs for Flink operator/metrics logging (CMK-encrypted log group)
###############################################################################

resource "aws_cloudwatch_log_group" "flink_app" {
  name              = "/aws/kinesisanalytics/${local.application_name}"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.flink_app.arn

  tags = local.common_tags
}

resource "aws_cloudwatch_log_stream" "flink_app" {
  name           = "${local.application_name}-operator-logs"
  log_group_name = aws_cloudwatch_log_group.flink_app.name
}

###############################################################################
# Service execution IAM role (trusted only by Kinesis Analytics)
###############################################################################

resource "aws_iam_role" "flink_app_exec" {
  name = "${local.application_name}-service-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowKinesisAnalyticsAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "flink_app_exec" {
  name        = "${local.application_name}-service-exec-policy"
  description = "Least-privilege permissions for the ${local.application_name} Flink application"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteApplicationLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.flink_app.arn,
          aws_cloudwatch_log_stream.flink_app.arn,
          "${aws_cloudwatch_log_group.flink_app.arn}:log-stream:*",
        ]
      },
      {
        Sid    = "ReadApplicationCode"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
        ]
        Resource = [
          aws_s3_bucket.code.arn,
          "${aws_s3_bucket.code.arn}/*",
        ]
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "flink_app_exec" {
  role       = aws_iam_role.flink_app_exec.name
  policy_arn = aws_iam_policy.flink_app_exec.arn
}

###############################################################################
# Kinesis Analytics V2 (Managed Service for Apache Flink) application
# At-rest encryption is enforced through the customer-managed KMS key chain:
# the S3 code bucket (SSE-KMS) and the KMS-encrypted code artifact both
# reference aws_kms_key.flink_app, whose key policy grants the service
# execution role kms:Decrypt / kms:GenerateDataKey.
###############################################################################

resource "aws_kinesisanalyticsv2_application" "flink_app" {
  name                   = local.application_name
  description            = "Apache Flink streaming application provisioned and managed by Terraform"
  runtime_environment    = "FLINK-1_18"
  service_execution_role = aws_iam_role.flink_app_exec.arn

  application_configuration {
    application_code_configuration {
      code_content_type = "ZIPLINK_OR_JARLINK"

      code_content {
        s3_content_location {
          bucket_arn     = aws_s3_bucket.code.arn
          file_key       = aws_s3_object.flink_code.key
          object_version = aws_s3_object.flink_code.version_id
        }
      }
    }

    environment_properties {
      property_group {
        property_group_id = "FLINK_APPLICATION_PROPERTIES"
        property_map      = var.flink_application_properties
      }
    }

    flink_application_configuration {
      monitoring_configuration {
        configuration_type = "CUSTOM"
        metrics_level      = "APPLICATION"
        log_level          = "INFO"
      }

      parallelism_configuration {
        configuration_type   = "CUSTOM"
        auto_scaling_enabled = false
        parallelism          = var.flink_parallelism
        parallelism_per_kpu  = var.flink_parallelism_per_kpu
      }
    }

    run_configuration {
      flink_run_configuration {
        allow_non_restored_state = false
      }
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.flink_app.arn
  }

  tags = merge(local.common_tags, {
    Name = local.application_name
  })

  depends_on = [
    aws_iam_role_policy_attachment.flink_app_exec,
    aws_s3_bucket_versioning.code,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs (non-sensitive identifiers only)
###############################################################################

output "application_arn" {
  description = "ARN of the Kinesis Analytics V2 (Apache Flink) application"
  value       = aws_kinesisanalyticsv2_application.flink_app.arn
}

output "application_name" {
  description = "Name of the Kinesis Analytics V2 (Apache Flink) application"
  value       = aws_kinesisanalyticsv2_application.flink_app.name
}

output "service_execution_role_arn" {
  description = "ARN of the application service execution IAM role"
  value       = aws_iam_role.flink_app_exec.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the application"
  value       = aws_kms_key.flink_app.arn
}

output "code_bucket_name" {
  description = "Name of the S3 bucket hosting the Flink application JAR"
  value       = aws_s3_bucket.code.id
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a consistent tag across resources."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  backup_bucket_name = "firehose-backup-${data.aws_region.current.name}-${data.aws_caller_identity.current.account_id}"

  tags = {
    Environment = var.environment
  }
}

# IAM role assumed by Kinesis Data Firehose to deliver to OpenSearch / S3 / CloudWatch Logs
resource "aws_iam_role" "firehose_opensearch" {
  name = "firehose-opensearch-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  tags = local.tags
}

# S3 backup bucket for failed documents
resource "aws_s3_bucket" "firehose_backup" {
  bucket = local.backup_bucket_name

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

# CloudWatch log group for Firehose delivery errors
resource "aws_cloudwatch_log_group" "firehose_errors" {
  name              = "/aws/kinesisfirehose/to-opensearch"
  retention_in_days = 14

  tags = local.tags
}

# Firehose requires a pre-existing log stream when CloudWatch logging is enabled
resource "aws_cloudwatch_log_stream" "firehose_errors" {
  name           = "firehose-delivery-errors"
  log_group_name = aws_cloudwatch_log_group.firehose_errors.name
}

# OpenSearch domain
resource "aws_opensearch_domain" "main" {
  domain_name    = "firehose-logs-domain"
  engine_version = "OpenSearch_2.13"

  cluster_config {
    instance_type  = "t3.small.search"
    instance_count = 1
  }

  ebs_options {
    ebs_enabled = true
    volume_type = "gp3"
    volume_size = 10
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }

  snapshot_options {
    automated_snapshot_start_hour = 23
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Resource-based domain policy: only the Firehose role may access the domain
resource "aws_opensearch_domain_policy" "firehose_access" {
  domain_name = aws_opensearch_domain.main.domain_name

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.firehose_opensearch.arn }
        Action = [
          "es:ESHttpGet",
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpPatch",
          "es:ESHttpDelete"
        ]
        Resource = "${aws_opensearch_domain.main.arn}/*"
      }
    ]
  })
}

# Least-privilege inline policy for the Firehose role
resource "aws_iam_role_policy" "firehose_opensearch_access" {
  name = "firehose-opensearch-access"
  role = aws_iam_role.firehose_opensearch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "OpenSearchDomainAccess"
        Effect = "Allow"
        Action = [
          "es:ESHttpGet",
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpPatch",
          "es:ESHttpDelete"
        ]
        Resource = [
          aws_opensearch_domain.main.arn
        ]
      },
      {
        Sid    = "S3BackupAccess"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.firehose_backup.arn,
          "${aws_s3_bucket.firehose_backup.arn}/*"
        ]
      },
      {
        Sid    = "FirehoseErrorLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.firehose_errors.arn}:*",
          aws_cloudwatch_log_stream.firehose_errors.arn
        ]
      }
    ]
  })
}

# Kinesis Data Firehose delivery stream (DirectPut -> OpenSearch)
resource "aws_kinesis_firehose_delivery_stream" "to_opensearch" {
  name        = "to-opensearch"
  destination = "opensearch"

  opensearch_configuration {
    domain_arn = aws_opensearch_domain.main.arn
    role_arn   = aws_iam_role.firehose_opensearch.arn
    index_name = "firehose-logs"

    s3_backup_mode = "FailedDocumentsOnly"

    buffering_size     = 5
    buffering_interval = 60

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_errors.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_errors.name
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose_opensearch.arn
      bucket_arn         = aws_s3_bucket.firehose_backup.arn
      buffering_size     = 5
      buffering_interval = 60
      compression_format = "GZIP"
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_opensearch_domain_policy.firehose_access,
    aws_iam_role_policy.firehose_opensearch_access
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)

  default = {
    Environment = "production"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }
}

variable "http_endpoint_url" {
  description = "URL of the HTTP endpoint destination (e.g., New Relic Firehose ingestion endpoint)."
  type        = string
  default     = "https://aws-api.newrelic.com/firehose/v1"
}

variable "http_endpoint_name" {
  description = "Human-readable name of the HTTP endpoint destination provider."
  type        = string
  default     = "New Relic"
}

# ------------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  firehose_stream_name = "http-endpoint-newrelic-delivery-stream"
}

# ------------------------------------------------------------------------------
# S3 backup/failed-records destination bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "firehose_backup" {
  bucket = "firehose-http-endpoint-backup-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# CloudWatch Logs for delivery success/error logging
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "firehose_http_endpoint" {
  name              = "/aws/kinesisfirehose/${local.firehose_stream_name}"
  retention_in_days = 14

  tags = var.tags
}

resource "aws_cloudwatch_log_stream" "http_endpoint_delivery" {
  name           = "HttpEndpointDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose_http_endpoint.name
}

resource "aws_cloudwatch_log_stream" "s3_backup_delivery" {
  name           = "S3BackupDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose_http_endpoint.name
}

# ------------------------------------------------------------------------------
# IAM role for the delivery stream
# ------------------------------------------------------------------------------

resource "aws_iam_role" "firehose_delivery_role" {
  name        = "firehose-http-endpoint-delivery-role"
  description = "IAM role assumed by Kinesis Data Firehose to deliver data to the HTTP endpoint and the S3 backup bucket."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

# Least-privilege inline policy granting the Firehose delivery stream access to
# the S3 backup bucket (failed records) and the Firehose CloudWatch log group only.
resource "aws_iam_role_policy" "firehose_delivery_policy" {
  name = "firehose-http-endpoint-delivery-policy"
  role = aws_iam_role.firehose_delivery_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FirehoseBackupBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.firehose_backup.arn,
          "${aws_s3_bucket.firehose_backup.arn}/*"
        ]
      },
      {
        Sid    = "FirehoseCloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream"
        ]
        Resource = [
          aws_cloudwatch_log_group.firehose_http_endpoint.arn,
          "${aws_cloudwatch_log_group.firehose_http_endpoint.arn}:log-stream:*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# HTTP endpoint access key (e.g., New Relic license key)
#
# ROTATION HAND-OFF: The value stored below is a deployment-bootstrap value
# generated by Terraform (random_password) so that automated, unattended
# applies require zero root-module inputs. The operator MUST rotate the stored
# secret out-of-band (Secrets Manager console/CLI or CI/CD secret injection)
# to the real New Relic license key after deployment. Never rotate it by
# committing the value to this repository or reintroducing it as a variable
# default / required input.
# ------------------------------------------------------------------------------

resource "random_password" "http_endpoint_access_key" {
  length  = 40
  special = false

  upper   = true
  lower   = true
  numeric = true
}

resource "aws_secretsmanager_secret" "http_endpoint_access_key" {
  name        = "firehose/http-endpoint-access-key"
  description = "Access key used by the Firehose HTTP endpoint destination to authenticate with the endpoint provider. Currently holds a Terraform-generated bootstrap value; the operator must rotate this to the real provider license key out-of-band after deployment."

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "http_endpoint_access_key" {
  secret_id     = aws_secretsmanager_secret.http_endpoint_access_key.id
  secret_string = random_password.http_endpoint_access_key.result
}

# ------------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream (DirectPut -> HTTP endpoint)
# ------------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "http_endpoint_stream" {
  name        = local.firehose_stream_name
  destination = "http_endpoint"

  server_side_encryption {
    enabled  = true
    key_type = "AWS_OWNED_CMK"
  }

  http_endpoint_configuration {
    url        = var.http_endpoint_url
    name       = var.http_endpoint_name
    access_key = aws_secretsmanager_secret_version.http_endpoint_access_key.secret_string
    role_arn   = aws_iam_role.firehose_delivery_role.arn

    # Near-real-time buffering hints: 1 MiB or 60 seconds.
    buffering_size     = 1
    buffering_interval = 60

    # Retry failed HTTP endpoint deliveries for up to 300 seconds.
    retry_duration = 300

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_http_endpoint.name
      log_stream_name = aws_cloudwatch_log_stream.http_endpoint_delivery.name
    }

    request_configuration {
      content_encoding = "NONE"
    }

    # Controls which records are routed to the s3_configuration backup
    # destination below; must remain a direct attribute of this block.
    s3_backup_mode = "FailedDataOnly"

    s3_configuration {
      role_arn   = aws_iam_role.firehose_delivery_role.arn
      bucket_arn = aws_s3_bucket.firehose_backup.arn
      prefix     = "failed-records/"

      buffering_size     = 1
      buffering_interval = 60
      compression_format = "GZIP"

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose_http_endpoint.name
        log_stream_name = aws_cloudwatch_log_stream.s3_backup_delivery.name
      }
    }
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "firehose_delivery_stream_arn" {
  description = "ARN of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.http_endpoint_stream.arn
}

output "firehose_delivery_stream_name" {
  description = "Name of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.http_endpoint_stream.name
}

output "firehose_backup_bucket_arn" {
  description = "ARN of the S3 backup bucket receiving failed records."
  value       = aws_s3_bucket.firehose_backup.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  delivery_stream_name = "firehose-s3-extended-destination"
  log_group_name       = "/aws/kinesisfirehose/${local.delivery_stream_name}"
  log_stream_name      = "s3-delivery-errors"
  s3_object_prefix     = "firehose-data/!{timestamp:yyyy/MM/dd}/"
  s3_error_prefix      = "processing-failed/!{firehose:error-output-type}/"
}

# ------------------------------------------------------------------------------
# S3 destination bucket for the Firehose delivery stream (stateful)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "firehose_destination" {
  # No explicit bucket name: Terraform assigns a globally unique name,
  # avoiding S3 namespace collisions in the target account.
  tags = {
    Name        = "firehose-destination"
    Purpose     = "kinesis-firehose-extended-s3-destination"
    Environment = "production"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# CloudWatch Logs for Firehose delivery error logging
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "firehose_delivery_logs" {
  name              = local.log_group_name
  retention_in_days = 30

  tags = {
    Name = local.log_group_name
  }
}

resource "aws_cloudwatch_log_stream" "firehose_delivery_errors" {
  name           = local.log_stream_name
  log_group_name = aws_cloudwatch_log_group.firehose_delivery_logs.name
}

# ------------------------------------------------------------------------------
# IAM role assumed by Firehose with least-privilege inline policy
# ------------------------------------------------------------------------------
resource "aws_iam_role" "firehose_delivery_role" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowFirehoseToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "firehose-delivery-role"
  }
}

resource "aws_iam_role_policy" "firehose_delivery_access" {
  name = "firehose-delivery-access"
  role = aws_iam_role.firehose_delivery_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FirehoseS3ObjectActions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:AbortMultipartUpload"
        ]
        Resource = "${aws_s3_bucket.firehose_destination.arn}/*"
      },
      {
        Sid    = "FirehoseS3BucketActions"
        Effect = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.firehose_destination.arn
      },
      {
        Sid      = "FirehosePutLogEvents"
        Effect   = "Allow"
        Action   = "logs:PutLogEvents"
        Resource = aws_cloudwatch_log_stream.firehose_delivery_errors.arn
      },
      {
        Sid    = "FirehoseLogGroupStreamManagement"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.firehose_delivery_logs.arn}:*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Kinesis Firehose delivery stream -> extended S3 destination
# ------------------------------------------------------------------------------
resource "aws_kinesis_firehose_delivery_stream" "firehose_to_s3" {
  name        = local.delivery_stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn            = aws_iam_role.firehose_delivery_role.arn
    bucket_arn          = aws_s3_bucket.firehose_destination.arn
    prefix              = local.s3_object_prefix
    error_output_prefix = local.s3_error_prefix
    buffering_size      = 5
    buffering_interval  = 300
    compression_format  = "GZIP"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_delivery_logs.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_delivery_errors.name
    }
  }

  # Firehose validates the delivery role's permissions at stream creation
  # time, so the inline policy must exist before the stream is created.
  depends_on = [aws_iam_role_policy.firehose_delivery_access]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Input variables
###############################################################################

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "dev"
  }
}

variable "confluence_server_url" {
  description = "Base URL of the Confluence Cloud instance to crawl."
  type        = string
  default     = "https://example.atlassian.net/wiki"
}

variable "proxy_host" {
  description = "Hostname of the outgoing web proxy used by the Confluence data source."
  type        = string
  default     = "proxy.example.com"
}

variable "proxy_port" {
  description = "Port of the outgoing web proxy used by the Confluence data source."
  type        = number
  default     = 3128
}

variable "proxy_username" {
  description = "Proxy server username. Supply the real value via tfvars or TF_VAR_proxy_username; never hardcode it here."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_PROXY_USERNAME"
}

variable "proxy_password" {
  description = "Proxy server password. Supply the real value via tfvars or TF_VAR_proxy_password; never hardcode it here."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_PROXY_PASSWORD"
}

variable "confluence_username" {
  description = "Confluence account username. Supply the real value via tfvars or TF_VAR_confluence_username; never hardcode it here."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_CONFLUENCE_USERNAME"
}

variable "confluence_api_key" {
  description = "Confluence Cloud API token stored as the connector password. Supply the real value via tfvars or TF_VAR_confluence_api_key; never hardcode it here."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_CONFLUENCE_API_TOKEN"
}

###############################################################################
# Static metadata lookups (pure local, no pre-existing infrastructure required)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id               = data.aws_caller_identity.current.account_id
  partition                = data.aws_partition.current.partition
  kendra_service_principal = "kendra.amazonaws.com"
}

###############################################################################
# Customer managed KMS key used to encrypt the Kendra index
###############################################################################

resource "aws_kms_key" "kendra" {
  description             = "Customer managed KMS key used to encrypt the Kendra index."
  enable_key_rotation     = true
  deletion_window_in_days = 30

  # Least-privilege key policy:
  #   - the account root retains administrative control of the key
  #   - the Kendra service principal is granted only the kms: actions required
  #     to use the key, restricted to callers from this AWS account
  #   - the Kendra index IAM role is granted only kms:Decrypt/kms:GenerateDataKey
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountAdministration"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowKendraServiceToUseKey"
        Effect    = "Allow"
        Principal = {
          Service = local.kendra_service_principal
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid       = "AllowKendraIndexRoleToUseKey"
        Effect    = "Allow"
        Principal = {
          AWS = aws_iam_role.kendra_index.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

###############################################################################
# IAM role assumed by Amazon Kendra for the index
###############################################################################

data "aws_iam_policy_document" "kendra_index_trust" {
  statement {
    sid     = "AllowKendraServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.kendra_service_principal]
    }
  }
}

resource "aws_iam_role" "kendra_index" {
  name               = "kendra-index-role"
  description        = "Role assumed by Amazon Kendra to create and manage the index."
  assume_role_policy = data.aws_iam_policy_document.kendra_index_trust.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "kendra_index" {
  name = "kendra-index-role-policy"
  role = aws_iam_role.kendra_index.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowDocumentOperationsOnIndex"
        Effect   = "Allow"
        Action   = ["kendra:BatchPutDocument", "kendra:BatchDeleteDocument"]
        Resource = [aws_kendra_index.main.arn]
      },
      {
        Sid      = "AllowKmsUsageForIndexEncryption"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [aws_kms_key.kendra.arn]
      }
    ]
  })
}

###############################################################################
# Kendra index (encrypted with the customer managed KMS key)
###############################################################################

resource "aws_kendra_index" "main" {
  name        = "kendra-enterprise-index"
  description = "Enterprise edition Kendra index encrypted with a customer managed KMS key."
  edition     = "ENTERPRISE_EDITION"

  # Per the hashicorp/aws ~> 5.0 schema, aws_kendra_index names the index role
  # attribute role_arn (the iam_role_arn naming belongs to other resources).
  role_arn = aws_iam_role.kendra_index.arn

  server_side_encryption_configuration {
    kms_key_id = aws_kms_key.kendra.arn
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Secrets Manager: proxy server credentials
###############################################################################

resource "aws_secretsmanager_secret" "proxy_credentials" {
  name        = "kendra/proxy-credentials"
  description = "Proxy server credentials consumed by the Kendra data source web proxy settings."
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "proxy_credentials" {
  secret_id = aws_secretsmanager_secret.proxy_credentials.id
  secret_string = jsonencode({
    username = var.proxy_username
    password = var.proxy_password
  })
}

###############################################################################
# Secrets Manager: Confluence connector authentication credentials
###############################################################################

resource "aws_secretsmanager_secret" "confluence_credentials" {
  name        = "kendra/confluence-credentials"
  description = "Confluence Cloud connector authentication credentials consumed by the Kendra data source."
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "confluence_credentials" {
  secret_id = aws_secretsmanager_secret.confluence_credentials.id
  secret_string = jsonencode({
    username = var.confluence_username
    password = var.confluence_api_key
  })
}

###############################################################################
# IAM role assumed by Amazon Kendra for the data source
###############################################################################

data "aws_iam_policy_document" "kendra_data_source_trust" {
  statement {
    sid     = "AllowKendraServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.kendra_service_principal]
    }
  }
}

resource "aws_iam_role" "kendra_data_source" {
  name               = "kendra-confluence-data-source-role"
  description        = "Role assumed by Amazon Kendra to crawl the Confluence data source."
  assume_role_policy = data.aws_iam_policy_document.kendra_data_source_trust.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "kendra_data_source" {
  name = "kendra-confluence-data-source-role-policy"
  role = aws_iam_role.kendra_data_source.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowDocumentOperationsOnIndex"
        Effect   = "Allow"
        Action   = ["kendra:BatchPutDocument", "kendra:BatchDeleteDocument"]
        Resource = [aws_kendra_index.main.arn]
      },
      {
        Sid    = "AllowReadingConnectorAndProxySecrets"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = [
          aws_secretsmanager_secret.confluence_credentials.arn,
          aws_secretsmanager_secret.proxy_credentials.arn
        ]
      }
    ]
  })
}

###############################################################################
# Kendra data source: Confluence Cloud via the template-connector pattern
#
# hashicorp/aws ~> 5.0 implements aws_kendra_data_source with only
# configuration.template_configuration for non-S3/web-crawler connectors, so the
# Confluence connector is declared here as type = "TEMPLATE" with a JSON
# template payload. The payload carries only the Confluence host, proxy
# endpoint, and Secrets Manager secret ARNs — never secret values.
###############################################################################

resource "aws_kendra_data_source" "confluence" {
  name        = "confluence-data-source"
  description = "Confluence Cloud data source crawled through a web proxy."
  index_id    = aws_kendra_index.main.id
  role_arn    = aws_iam_role.kendra_data_source.arn
  type        = "TEMPLATE"

  configuration {
    template_configuration {
      template = jsonencode({
        connectionConfiguration = {
          repositoryEndpointMetadata = {
            # Confluence Cloud host URL (cloud flavor expressed via the host URL)
            ConfluenceHostUrl = var.confluence_server_url
            # Connector authentication: Secrets Manager secret ARN only
            Credentials = aws_secretsmanager_secret.confluence_credentials.arn
            # Outgoing web proxy endpoint traversed by the crawler
            Host             = var.proxy_host
            Port             = tostring(var.proxy_port)
            ProxyCredentials = aws_secretsmanager_secret.proxy_credentials.arn
          }
        }
        repositoryConfigurations = {
          pages = {
            crawl         = true
            fieldMappings = []
          }
          blog = {
            crawl         = true
            fieldMappings = []
          }
          database = {
            crawl         = true
            fieldMappings = []
          }
          space = {
            crawl         = true
            fieldMappings = []
          }
          attachment = {
            crawl         = true
            fieldMappings = []
          }
        }
        additionalProperties = {
          isCrawlAcl       = true
          isCrawlChangelog = false
        }
        type     = "CONFLUENCE"
        version  = "1.0.0"
        syncMode = "FULL_CRAWL"
      })
    }
  }

  tags = var.tags
}

###############################################################################
# Outputs (non-sensitive only)
###############################################################################

output "kendra_index_id" {
  description = "ID of the Kendra index."
  value       = aws_kendra_index.main.id
}

output "kendra_index_arn" {
  description = "ARN of the Kendra index."
  value       = aws_kendra_index.main.arn
}

output "kendra_data_source_id" {
  description = "ID of the Confluence Kendra data source."
  value       = aws_kendra_data_source.confluence.id
}

output "kendra_data_source_arn" {
  description = "ARN of the Confluence Kendra data source."
  value       = aws_kendra_data_source.confluence.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Standard tags applied to the hosted zone for ownership and cost-allocation compliance."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  common_tags = var.tags
}

resource "aws_route53_zone" "example53" {
  name = "example53.com"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "zone_id" {
  description = "The ID of the example53.com public hosted zone."
  value       = aws_route53_zone.example53.zone_id
}

output "name_servers" {
  description = "The authoritative name servers for example53.com, to be configured at the domain registrar for delegation."
  value       = aws_route53_zone.example53.name_servers
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  health_check_path = "/health"
  www_record_name   = "www.${aws_route53_zone.main.name}"
}

variable "domain_name" {
  description = "Domain name of the Route 53 hosted zone to create."
  type        = string
  default     = "example.com"
}

variable "tags" {
  description = "Tags applied to all Route 53 resources."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
    Purpose     = "active-active-failover"
  }
}

variable "endpoint_ips" {
  description = "Public IPv4 addresses of the primary and secondary application endpoints."
  type        = map(string)
  default = {
    primary   = "203.0.113.10"
    secondary = "203.0.113.20"
  }
}

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn              = "primary.${aws_route53_zone.main.name}"
  type              = "HTTPS"
  port              = 443
  resource_path     = local.health_check_path
  request_interval  = 30
  failure_threshold = 3
  measure_latency   = true
  enable_sni        = true

  tags = var.tags
}

resource "aws_route53_health_check" "secondary_health_check" {
  fqdn              = "secondary.${aws_route53_zone.main.name}"
  type              = "HTTPS"
  port              = 443
  resource_path     = local.health_check_path
  request_interval  = 30
  failure_threshold = 3
  measure_latency   = true
  enable_sni        = true

  tags = var.tags
}

resource "aws_route53_record" "primary" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.www_record_name
  type    = "A"
  ttl     = 60

  records        = [var.endpoint_ips["primary"]]
  set_identifier = "PRIMARY"
  health_check_id = aws_route53_health_check.primary_health_check.id

  failover_routing_policy {
    type = "PRIMARY"
  }
}

resource "aws_route53_record" "secondary" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.www_record_name
  type    = "A"
  ttl     = 60

  records        = [var.endpoint_ips["secondary"]]
  set_identifier = "SECONDARY"
  health_check_id = aws_route53_health_check.secondary_health_check.id

  failover_routing_policy {
    type = "SECONDARY"
  }
}

output "hosted_zone_id" {
  description = "ID of the main Route 53 hosted zone."
  value       = aws_route53_zone.main.zone_id
}

output "hosted_zone_name_servers" {
  description = "Delegated name servers for the main hosted zone."
  value       = aws_route53_zone.main.name_servers
}

output "primary_health_check_id" {
  description = "ID of the primary endpoint health check."
  value       = aws_route53_health_check.primary_health_check.id
}

output "secondary_health_check_id" {
  description = "ID of the secondary endpoint health check."
  value       = aws_route53_health_check.secondary_health_check.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "domain_name" {
  description = "The DNS zone name used for the Route 53 public hosted zone."
  type        = string
  default     = "example.com"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "greenfield"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Pure metadata lookups (static provider data only, no pre-existing infrastructure)
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ------------------------------------------------------------------------------
# Networking
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = var.tags
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = var.tags
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = var.tags
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = var.tags
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = var.tags
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# Security groups
# ------------------------------------------------------------------------------

resource "aws_security_group" "alb_sg" {
  name        = "web-alb-sg"
  description = "Public ALB security group: inbound HTTP/HTTPS from the internet only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.tags
}

resource "aws_security_group" "instance_sg" {
  name        = "web-instance-sg"
  description = "Web server security group: inbound HTTP from the ALB security group only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the ALB security group only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Web servers (one per ALB target group)
# ------------------------------------------------------------------------------

resource "aws_instance" "primary" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_a.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.instance_sg.id]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
    echo '<h1>Primary endpoint</h1>' > /var/www/html/index.html
  EOF

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
    volume_size = 8
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = var.tags
}

resource "aws_instance" "secondary" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_b.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.instance_sg.id]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
    echo '<h1>Secondary endpoint</h1>' > /var/www/html/index.html
  EOF

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
    volume_size = 8
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Load balancers (primary and secondary failover endpoints)
# ------------------------------------------------------------------------------

resource "aws_lb_target_group" "primary" {
  name                 = "primary-web-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = var.tags
}

resource "aws_lb_target_group" "secondary" {
  name                 = "secondary-web-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = var.tags
}

resource "aws_lb_target_group_attachment" "primary" {
  target_group_arn = aws_lb_target_group.primary.arn
  target_id        = aws_instance.primary.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "secondary" {
  target_group_arn = aws_lb_target_group.secondary.arn
  target_id        = aws_instance.secondary.id
  port             = 80
}

resource "aws_lb" "primary" {
  name                       = "primary-web-alb"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb_sg.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true

  tags = var.tags
}

resource "aws_lb" "secondary" {
  name                       = "secondary-web-alb"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb_sg.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true

  tags = var.tags
}

resource "aws_lb_listener" "primary" {
  load_balancer_arn = aws_lb.primary.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.primary.arn
  }

  tags = var.tags
}

resource "aws_lb_listener" "secondary" {
  load_balancer_arn = aws_lb.secondary.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.secondary.arn
  }

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Route 53 hosted zone and health checks
# ------------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name = var.domain_name

  lifecycle {
    prevent_destroy = true
  }

  tags = var.tags
}

resource "aws_route53_health_check" "primary" {
  fqdn              = aws_lb.primary.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = var.tags
}

resource "aws_route53_health_check" "secondary" {
  fqdn              = aws_lb.secondary.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Route 53 traffic policy: failover from the primary ALB to the secondary ALB
# ------------------------------------------------------------------------------

resource "aws_route53_traffic_policy" "failover" {
  name = "www-failover-policy"

  document = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Resources = {
      failover_rule_block = {
        Type = "AWS::Route53::TrafficPolicyVersion"
        Properties = {
          RecordType = "A"
          StartRule = {
            RuleName = "primary_secondary_failover"
          }
          Rules = {
            primary_secondary_failover = {
              Type = "failover"
              Primary = {
                EndpointName = "primary_alb_endpoint"
              }
              Secondary = {
                EndpointName = "secondary_alb_endpoint"
              }
            }
          }
          Endpoints = {
            primary_alb_endpoint = {
              Type        = "endpoint"
              Value       = aws_lb.primary.dns_name
              HealthCheck = aws_route53_health_check.primary.id
            }
            secondary_alb_endpoint = {
              Type        = "endpoint"
              Value       = aws_lb.secondary.dns_name
              HealthCheck = aws_route53_health_check.secondary.id
            }
          }
        }
      }
    }
  })
}

resource "aws_route53_traffic_policy_instance" "www_failover" {
  name                   = "www.${var.domain_name}"
  hosted_zone_id         = aws_route53_zone.main.zone_id
  traffic_policy_id      = aws_route53_traffic_policy.failover.id
  traffic_policy_version = aws_route53_traffic_policy.failover.version
  ttl                    = 60

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "zone_name_servers" {
  description = "The authoritative name servers assigned to the public hosted zone."
  value       = aws_route53_zone.main.name_servers
}

output "www_failover_record_name" {
  description = "The DNS name of the traffic policy instance record (www.<domain_name>)."
  value       = aws_route53_traffic_policy_instance.www_failover.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.2.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name    = "eks-fargate-cluster"
  vpc_cidr        = "10.0.0.0/16"
  public_subnets  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnets = ["10.0.11.0/24", "10.0.12.0/24"]
  az_count        = 2
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnets[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name                                          = "${local.cluster_name}-public-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                      = "1"
  }
}

resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name                                          = "${local.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/internal-elb"             = "1"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = local.az_count
  domain = "vpc"

  tags = {
    Name = "${local.cluster_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = local.az_count
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.cluster_name}-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = local.az_count
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${local.cluster_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_iam_role" "eks_cluster" {
  name = "${local.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEKSToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.cluster_name}-cluster-role"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "eks_fargate_pod_execution" {
  name = "${local.cluster_name}-fargate-pod-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEksFargatePodsToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "eks-fargate-pods.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.cluster_name}-fargate-pod-execution-role"
  }
}

resource "aws_iam_role_policy_attachment" "eks_fargate_pod_execution_policy" {
  role       = aws_iam_role.eks_fargate_pod_execution.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSFargatePodExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_fargate_pod_execution_ecr_readonly" {
  role       = aws_iam_role.eks_fargate_pod_execution.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = concat(aws_subnet.private[*].id, aws_subnet.public[*].id)
    endpoint_private_access = true
    endpoint_public_access  = true
  }

  depends_on = [aws_iam_role_policy_attachment.eks_cluster_policy]

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.cluster_name
  }
}

resource "aws_eks_fargate_profile" "kube_system" {
  cluster_name           = aws_eks_cluster.main.name
  fargate_profile_name   = "kube-system"
  pod_execution_role_arn = aws_iam_role.eks_fargate_pod_execution.arn
  subnet_ids             = aws_subnet.private[*].id

  selector {
    namespace = "kube-system"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_fargate_pod_execution_policy,
    aws_iam_role_policy_attachment.eks_fargate_pod_execution_ecr_readonly,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_eks_cluster_auth" "main" {
  name = aws_eks_cluster.main.name
}

resource "null_resource" "coredns_fargate_patch" {
  triggers = {
    cluster_endpoint = aws_eks_cluster.main.endpoint
    cluster_ca       = aws_eks_cluster.main.certificate_authority[0].data
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]

    command = <<-EOT
      kubectl \
        --server ${aws_eks_cluster.main.endpoint} \
        --certificate-authority <(echo '${aws_eks_cluster.main.certificate_authority[0].data}' | base64 --decode) \
        --token ${data.aws_eks_cluster_auth.main.token} \
        patch deployment coredns \
        --namespace kube-system \
        --type json \
        --patch='[{"op": "remove", "path": "/metadata/annotations/eks.amazonaws.com~1compute-type"}]'
    EOT
  }

  depends_on = [aws_eks_fargate_profile.kube_system]
}

###############################################################################
# Self-contained EKS configuration for cluster "example" (greenfield account).
# Every dependency (network, IAM, KMS) is created within this file.
###############################################################################

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static provider metadata: AZ names are looked up, never hardcoded.
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name = "example"
}

# -----------------------------------------------------------------------------
# KMS key backing envelope encryption of Kubernetes secrets
# -----------------------------------------------------------------------------

resource "aws_kms_key" "eks_secrets" {
  description             = "Envelope encryption key for Kubernetes secrets of EKS cluster example"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "${local.cluster_name}-secrets-key"
  }
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 10)
  map_public_ip_on_launch = true

  tags = {
    Name                            = "${local.cluster_name}-public-a"
    "kubernetes.io/cluster/example" = "shared"
    "kubernetes.io/role/elb"        = "1"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 11)
  map_public_ip_on_launch = true

  tags = {
    Name                            = "${local.cluster_name}-public-b"
    "kubernetes.io/cluster/example" = "shared"
    "kubernetes.io/role/elb"        = "1"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Cluster IAM role and managed policy attachments
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster" {
  name = "${local.cluster_name}-eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEksToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster.name
}

# Least-privilege grant allowing the cluster role to use the KMS key for
# secret envelope encryption (the AWS-managed policies above do not cover KMS).
resource "aws_iam_role_policy" "eks_cluster_kms" {
  name = "${local.cluster_name}-eks-cluster-kms"
  role = aws_iam_role.eks_cluster.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EKSSecretEnvelopeEncryption"
        Effect = "Allow"
        Action = [
          "kms:CreateGrant",
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncrypt*"
        ]
        Resource = aws_kms_key.eks_secrets.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# EKS cluster
# -----------------------------------------------------------------------------

resource "aws_eks_cluster" "example" {
  name     = "example"
  role_arn = aws_iam_role.eks_cluster.arn

  # Control-plane exposure is intentional and explicit:
  # - endpoint_private_access = true: API server is reachable from inside the VPC.
  # - endpoint_public_access  = true: API server is reachable from the internet
  #   for operator kubectl access (default public CIDR scope 0.0.0.0/0).
  vpc_config {
    subnet_ids              = [aws_subnet.public_a.id, aws_subnet.public_b.id]
    endpoint_private_access = true
    endpoint_public_access  = true
  }

  # Envelope encryption of Kubernetes secrets, backed by the KMS key created
  # above (key rotation enabled; no external key ARNs are referenced).
  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks_secrets.arn
    }
  }

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  # Cluster creation waits until all IAM permissions are in place, and
  # destruction ordering is deterministic (policies outlive the cluster).
  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_cluster_kms
  ]

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "example"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cluster_endpoint" {
  description = "Endpoint of the EKS API server for cluster example; used to configure clients (e.g. kubectl) against the API server."
  value       = aws_eks_cluster.example.endpoint
}

output "kubeconfig_certificate_authority_data" {
  description = "Base64-encoded certificate authority (CA) bundle for the EKS cluster; used in generated kubeconfig files."
  value       = aws_eks_cluster.example.certificate_authority[0].data
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name    = "example"
  node_group_name = "example"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking: VPC, subnets, and routing for the EKS cluster and worker nodes
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-igw"
    }
  )
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name                                          = "${local.cluster_name}-public-a"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
      "kubernetes.io/role/elb"                      = "1"
    }
  )
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name                                          = "${local.cluster_name}-public-b"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
      "kubernetes.io/role/elb"                      = "1"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-public-rt"
    }
  )
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM: EKS control plane role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster_role" {
  name = "${local.cluster_name}-eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

# -----------------------------------------------------------------------------
# KMS: customer-managed key for envelope encryption of Kubernetes secrets
# -----------------------------------------------------------------------------

resource "aws_kms_key" "eks_secrets" {
  description             = "Encrypts Kubernetes secrets for the ${local.cluster_name} EKS cluster"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.cluster_name}-eks-secrets"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "eks_cluster_secrets_encryption" {
  name = "${local.cluster_name}-secrets-encryption"
  role = aws_iam_role.eks_cluster_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:CreateGrant",
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.eks_secrets.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# EKS control plane
# -----------------------------------------------------------------------------

resource "aws_eks_cluster" "example" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = [
      aws_subnet.public_a.id,
      aws_subnet.public_b.id
    ]

    endpoint_private_access = true
    endpoint_public_access  = true
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks_secrets.arn
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_cluster_secrets_encryption
  ]

  tags = merge(
    local.common_tags,
    {
      Name = local.cluster_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# IAM: EKS managed node group (worker node) role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eks_node_role" {
  name = "${local.cluster_name}-eks-node-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_node_worker_policy" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni_policy" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_registry_read_only" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# -----------------------------------------------------------------------------
# EKS managed node group
# -----------------------------------------------------------------------------

resource "aws_eks_node_group" "example" {
  cluster_name    = aws_eks_cluster.example.name
  node_group_name = local.node_group_name
  node_role_arn   = aws_iam_role.eks_node_role.arn

  subnet_ids = [
    aws_subnet.public_a.id,
    aws_subnet.public_b.id
  ]

  capacity_type  = "ON_DEMAND"
  instance_types = ["t3.medium"]

  scaling_config {
    desired_size = 1
    max_size     = 2
    min_size     = 1
  }

  update_config {
    max_unavailable = 1
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_node_worker_policy,
    aws_iam_role_policy_attachment.eks_node_cni_policy,
    aws_iam_role_policy_attachment.eks_node_registry_read_only
  ]

  tags = merge(
    local.common_tags,
    {
      Name = local.node_group_name
    }
  )
}

