      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "source_bucket_name" {
  description = "Physical S3 bucket name for the source bucket 'a' (3-63 chars, lowercase letters, numbers, hyphens)."
  type        = string
  default     = "a-source-bucket-logs-demo"
}

locals {
  log_prefix = "log/"
}

# -----------------------------------------------------------------------------
# Source bucket "a"
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "a" {
  bucket = var.source_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "a" {
  bucket = aws_s3_bucket.a.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "a" {
  bucket = aws_s3_bucket.a.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "a" {
  bucket = aws_s3_bucket.a.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# Target logging bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "logging" {
  bucket = "logging-680235478471"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  bucket = aws_s3_bucket.logging.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  bucket = aws_s3_bucket.logging.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "logging" {
  bucket = aws_s3_bucket.logging.id

  versioning_configuration {
    status = "Enabled"
  }
}

# With BucketOwnerEnforced, ACLs are disabled and log delivery must be
# authorized through this bucket policy instead.
resource "aws_s3_bucket_ownership_controls" "logging" {
  bucket = aws_s3_bucket.logging.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "logging" {
  bucket = aws_s3_bucket.logging.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3ServerAccessLogsPolicy"
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.logging.arn}/${local.log_prefix}*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.a.arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Enable server access logging on bucket "a"
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "a_logging" {
  bucket        = aws_s3_bucket.a.id
  target_bucket = aws_s3_bucket.logging.id
  target_prefix = local.log_prefix

  depends_on = [
    aws_s3_bucket_ownership_controls.logging,
    aws_s3_bucket_policy.logging,
  ]
}

