    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "pike_bucket" {
  bucket = "pike-680235478471"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "pike_bucket_pab" {
  bucket = aws_s3_bucket.pike_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "pike_bucket_encryption" {
  bucket = aws_s3_bucket.pike_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "pike_bucket_versioning" {
  bucket = aws_s3_bucket.pike_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "pike_bucket_policy" {
  bucket = aws_s3_bucket.pike_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.pike_bucket.arn,
          "${aws_s3_bucket.pike_bucket.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "my_bucket" {
  bucket              = "mybucket"
  object_lock_enabled = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  versioning_configuration {
    status = "Enabled"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_object_lock_configuration" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = 5
    }
  }

  depends_on = [aws_s3_bucket_versioning.my_bucket]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

output "bucket_id" {
  description = "The ID (name) of the S3 bucket with versioning and object lock enabled."
  value       = aws_s3_bucket.my_bucket.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket with versioning and object lock enabled."
  value       = aws_s3_bucket.my_bucket.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Globally-unique bucket name
# S3 bucket names allow only lowercase letters, digits, and hyphens
# (underscores are illegal), so "your_bucket_name" becomes "your-bucket-name"
# with a random suffix to guarantee global uniqueness.
# ---------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

locals {
  bucket_name = "your-bucket-name-${random_id.bucket_suffix.hex}"
}

# ---------------------------------------------------------------------------
# S3 bucket (stateful resource — protected from destruction)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket = local.bucket_name

  tags = {
    Name      = local.bucket_name
    ManagedBy = "terraform"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# ---------------------------------------------------------------------------
# Object upload
# NOTE: "path/to/file" must exist on disk (relative to the configuration
# directory) before plan/apply runs; contents are never inlined as plaintext.
# ---------------------------------------------------------------------------
resource "aws_s3_object" "object" {
  bucket = aws_s3_bucket.main.id
  key    = "new_object_key"
  source = "path/to/file"

  depends_on = [
    aws_s3_bucket_public_access_block.main,
    aws_s3_bucket_server_side_encryption_configuration.main,
    aws_s3_bucket_versioning.main,
    aws_s3_bucket_ownership_controls.main,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Project name used as the prefix for resource Name tags."
  type        = string
  default     = "amazon-linux-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "instance_type" {
  description = "Instance type with 4 vCPUs (2 cores x 2 threads per core)."
  type        = string
  default     = "t3.xlarge"
}

locals {
  common_tags = {
    environment = var.environment
    project     = var.project_name
    managed_by  = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-subnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "instance" {
  name        = "${var.project_name}-instance-sg"
  description = "Ingress limited to HTTP/HTTPS from anywhere and SSH from inside the VPC only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH restricted to the VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-instance-sg"
  })
}

resource "aws_instance" "amazon_linux_2" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  associate_public_ip_address = true

  cpu_options {
    core_count       = 2
    threads_per_core = 2
  }

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-instance"
  })
}

output "instance_id" {
  description = "ID of the EC2 instance."
  value       = aws_instance.amazon_linux_2.id
}

output "instance_public_ip" {
  description = "Public IP address of the EC2 instance."
  value       = aws_instance.amazon_linux_2.public_ip
}

output "resolved_ami_id" {
  description = "Latest Amazon Linux 2 AMI ID resolved at apply time."
  value       = data.aws_ami.amazon_linux_2.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (all defaulted so `terraform apply` runs unattended)
###############################################################################

variable "project" {
  description = "Project name used as the prefix for resource names and tags."
  type        = string
  default     = "shared_storage"
}

variable "environment" {
  description = "Environment tag applied to every resource."
  type        = string
  default     = "dev"
}

variable "instance_type" {
  description = "EC2 instance type for the private application nodes."
  type        = string
  default     = "t3.micro"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

###############################################################################
# Data sources (pure static/well-known lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  efs_mount_user_data = <<-EOT
    #!/bin/bash
    set -eux

    EFS_DNS_NAME="${aws_efs_file_system.shared.dns_name}"

    # Install the NFS client utilities required to mount EFS
    yum install -y nfs-utils

    # Create the shared EFS mount point
    mkdir -p /mnt/efs

    # Persist the EFS mount across reboots
    echo "$EFS_DNS_NAME:/ /mnt/efs nfs4 nfsvers=4.1,rsize=1048576,wsize=1048576,hard,timeo=600,retrans=2,noresvport,_netdev 0 0" >> /etc/fstab

    # Mount immediately, retrying while the mount target finishes provisioning
    attempt=1
    until mount -t nfs4 -o nfsvers=4.1,rsize=1048576,wsize=1048576,hard,timeo=600,retrans=2,noresvport "$EFS_DNS_NAME:/" /mnt/efs; do
      if [ "$attempt" -ge 30 ]; then
        echo "ERROR: failed to mount EFS after $attempt attempts" >&2
        exit 1
      fi
      attempt=$((attempt + 1))
      sleep 10
    done

    echo "EFS mounted successfully at /mnt/efs"
  EOT
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-main-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-main-igw"
  })
}

# Public subnet in the first AZ, hosting the NAT gateway only
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-public-a"
  })
}

# Private subnets, one per AZ, no auto-assign public IPs
resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-b"
  })
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${var.project}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${var.project}-main-nat"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Private route table: outbound-only internet access through the NAT gateway
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-rt"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security groups (standalone rules to avoid SG-to-SG reference cycles)
###############################################################################

# EC2 instances: no 0.0.0.0/0 ingress; private-only access via SSM
resource "aws_security_group" "ec2" {
  name        = "${var.project}-ec2-sg"
  description = "Security group for the private EC2 instances"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-ec2-sg"
  })
}

# EFS mount targets
resource "aws_security_group" "efs" {
  name        = "${var.project}-efs-sg"
  description = "Security group for the EFS mount targets"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-efs-sg"
  })
}

resource "aws_security_group_rule" "ec2_egress_https" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.ec2.id
  description       = "Allow outbound HTTPS for package updates and SSM"
}

resource "aws_security_group_rule" "ec2_egress_http" {
  type              = "egress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.ec2.id
  description       = "Allow outbound HTTP for package updates"
}

resource "aws_security_group_rule" "ec2_egress_nfs" {
  type                     = "egress"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.efs.id
  security_group_id        = aws_security_group.ec2.id
  description              = "Allow NFS traffic to the EFS mount targets only"
}

# NFS 2049 ingress restricted to the EC2 instances' security group only
resource "aws_security_group_rule" "efs_ingress_nfs" {
  type                     = "ingress"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.ec2.id
  security_group_id        = aws_security_group.efs.id
  description              = "Allow NFS from the EC2 instances only"
}

###############################################################################
# EFS shared storage
###############################################################################

resource "aws_efs_file_system" "shared" {
  creation_token   = "${var.project}-shared-efs"
  encrypted        = true
  performance_mode = "generalPurpose"

  tags = merge(local.common_tags, {
    Name = "${var.project}-shared-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# One mount target per private subnet so every instance has an in-AZ target
resource "aws_efs_mount_target" "private_a" {
  file_system_id  = aws_efs_file_system.shared.id
  subnet_id       = aws_subnet.private_a.id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_mount_target" "private_b" {
  file_system_id  = aws_efs_file_system.shared.id
  subnet_id       = aws_subnet.private_b.id
  security_groups = [aws_security_group.efs.id]
}

###############################################################################
# IAM: keyless SSM management via instance profile
###############################################################################

resource "aws_iam_role" "ec2_ssm" {
  name = "${var.project}-ec2-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2ToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.project}-ec2-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ec2_ssm.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "${var.project}-ec2-instance-profile"
  role = aws_iam_role.ec2_ssm.name

  depends_on = [aws_iam_role_policy_attachment.ssm_managed_instance_core]
}

###############################################################################
# EC2 instances (exactly 2, private subnets, one per AZ)
###############################################################################

resource "aws_instance" "node_a" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private_a.id
  vpc_security_group_ids      = [aws_security_group.ec2.id]
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  user_data                   = base64encode(local.efs_mount_user_data)
  user_data_replace_on_change = true

  root_block_device {
    volume_type = "gp3"
    volume_size = 20
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-node-a"
  })

  depends_on = [aws_efs_mount_target.private_a]
}

resource "aws_instance" "node_b" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private_b.id
  vpc_security_group_ids      = [aws_security_group.ec2.id]
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  user_data                   = base64encode(local.efs_mount_user_data)
  user_data_replace_on_change = true

  root_block_device {
    volume_type = "gp3"
    volume_size = 20
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-node-b"
  })

  depends_on = [aws_efs_mount_target.private_b]
}

###############################################################################
# Outputs
###############################################################################

output "efs_file_system_id" {
  description = "ID of the shared EFS file system."
  value       = aws_efs_file_system.shared.id
}

output "efs_dns_name" {
  description = "DNS name of the shared EFS file system."
  value       = aws_efs_file_system.shared.dns_name
}

output "node_a_private_ip" {
  description = "Private IP address of the first EC2 instance."
  value       = aws_instance.node_a.private_ip
}

output "node_b_private_ip" {
  description = "Private IP address of the second EC2 instance."
  value       = aws_instance.node_b.private_ip
}

output "instance_private_ips" {
  description = "Private IP addresses of both EC2 instances."
  value       = [aws_instance.node_a.private_ip, aws_instance.node_b.private_ip]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to all taggable resources in this configuration."
  type        = map(string)
  default = {
    Name        = "app-redis-rbac"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  redis_user_id       = "app_redis_user"
  redis_user_name     = "app_redis_user"
  redis_user_group_id = "app-redis-user-group"
}

# Customer-managed KMS key used to encrypt the Redis user password secret.
resource "aws_kms_key" "redis_user_secret" {
  description             = "KMS key for the ElastiCache Redis user password secret"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Credential for the Redis user. Never a literal value; referenced by the
# ElastiCache user and by Secrets Manager only.
resource "random_password" "redis_user_password" {
  length           = 32
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}:?"
  special          = true
}

# ElastiCache (Redis) RBAC user with least-privilege key scoping and command
# categories. The user is enabled only on the app:* key pattern, with read and
# write command groups, while dangerous and administrative command categories
# are explicitly denied.
resource "aws_elasticache_user" "redis_user" {
  user_id       = local.redis_user_id
  user_name     = local.redis_user_name
  engine        = "redis"
  access_string = "on ~app:* +@read +@write -@dangerous -@admin"

  # Password-based authentication: providing `passwords` with
  # `no_password_required = false` provisions this user with the ElastiCache
  # authentication type "password".
  no_password_required = false
  passwords            = [random_password.redis_user_password.result]

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# The generated credential is stored in AWS Secrets Manager, encrypted with
# the customer-managed KMS key above. Only the secret ARN is ever referenced
# by other resources; the secret value itself is never exposed.
resource "aws_secretsmanager_secret" "redis_user_password" {
  name        = "elasticache/redis-user/${local.redis_user_id}"
  description = "Password for the ElastiCache Redis user ${local.redis_user_name}"
  kms_key_id  = aws_kms_key.redis_user_secret.arn
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redis_user_password" {
  secret_id = aws_secretsmanager_secret.redis_user_password.id
  secret_string = jsonencode({
    username = aws_elasticache_user.redis_user.user_name
    password = random_password.redis_user_password.result
  })
}

# User group that attaches the Redis user so it can be associated with
# replication groups and used by clients.
resource "aws_elasticache_user_group" "redis_user_group" {
  user_group_id = local.redis_user_group_id
  engine        = "redis"
  user_ids      = [aws_elasticache_user.redis_user.user_id]
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "redis_user_id" {
  description = "The ID of the ElastiCache Redis user."
  value       = aws_elasticache_user.redis_user.id
}

output "redis_user_arn" {
  description = "The ARN of the ElastiCache Redis user."
  value       = aws_elasticache_user.redis_user.arn
}

output "redis_user_group_id" {
  description = "The ID of the ElastiCache Redis user group."
  value       = aws_elasticache_user_group.redis_user_group.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  engine        = "redis"
  user_id       = "app-user-001"
  user_name     = "app-user-001"
  user_group_id = "app-user-group-001"

  secret_name = "elasticache/${local.user_id}/password"

  # Least-privilege Redis ACL:
  #   * enabled user ("on")
  #   * key access limited to the "cache:*" key pattern
  #   * pub/sub limited to the "cache-events:*" channel pattern
  #   * all commands revoked first ("-@all"), then only the required command
  #     categories are granted; "@dangerous" is revoked last so commands such
  #     as FLUSHALL, KEYS and CONFIG can never be executed.
  access_string = "on ~cache:* -@all +@read +@write +@connection +@pubsub -@dangerous &cache-events:*"

  common_tags = {
    Component = "cache"
    ManagedBy = "terraform"
  }
}

# The password is generated, never hardcoded. ElastiCache requires 16-128
# printable characters and rejects double quotes, slashes, "@" and spaces,
# all of which are excluded from the special-character set below.
resource "random_password" "elasticache_user_password" {
  length           = 32
  special          = true
  min_lower        = 1
  min_upper        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_kms_key" "elasticache_secrets" {
  description             = "Encrypts the ElastiCache user password secret"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "elasticache-user-secrets"
  })
}

resource "aws_secretsmanager_secret" "elasticache_user_password_secret" {
  name                    = local.secret_name
  description             = "Password for the ElastiCache (Redis) user ${local.user_id}"
  kms_key_id              = aws_kms_key.elasticache_secrets.arn
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = local.secret_name
  })
}

resource "aws_secretsmanager_secret_version" "elasticache_user_password_secret_version" {
  secret_id     = aws_secretsmanager_secret.elasticache_user_password_secret.id
  secret_string = random_password.elasticache_user_password.result
}

resource "aws_elasticache_user" "app_user" {
  user_id   = local.user_id
  user_name = local.user_name
  engine    = local.engine

  access_string        = local.access_string
  no_password_required = false
  passwords = [
    aws_secretsmanager_secret_version.elasticache_user_password_secret_version.secret_string,
  ]

  tags = merge(local.common_tags, {
    Name = local.user_id
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Membership is owned exclusively by aws_elasticache_user_group_association
# below; user_ids is intentionally omitted to avoid dual management of the
# same ModifyUserGroup API state. The group is created empty, which the AWS
# CreateUserGroup API accepts.
resource "aws_elasticache_user_group" "main" {
  engine        = local.engine
  user_group_id = local.user_group_id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_user_group_association" "app_user_membership" {
  user_group_id = aws_elasticache_user_group.main.user_group_id
  user_id       = aws_elasticache_user.app_user.user_id
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging"
  type        = string
  default     = "redshift-analytics"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "dev"
}

locals {
  name_prefix = lower("${var.project_name}-${var.environment}")

  common_tags = {
    project     = var.project_name
    environment = var.environment
    managed_by  = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "redshift_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-a" })
}

resource "aws_subnet" "redshift_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-b" })
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Allow Redshift connections on TCP 5439 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift from within the VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-sg" })
}

resource "aws_redshift_subnet_group" "main" {
  name       = "${local.name_prefix}-redshift-subnet-group"
  subnet_ids = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-subnet-group" })
}

resource "aws_kms_key" "redshift" {
  description             = "Customer managed key for Redshift cluster encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-kms" })
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift"
  target_key_id = aws_kms_key.redshift.key_id
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "${local.name_prefix}-cluster"
  database_name      = "analyticsdb"
  cluster_type       = "single-node"
  node_type          = "ra3.xlplus"
  number_of_nodes    = 1
  port               = 5439

  master_username                   = "admin"
  manage_master_password            = true
  master_password_secret_kms_key_id = aws_kms_key.redshift.key_id

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]

  publicly_accessible = false
  encrypted           = true
  kms_key_id          = aws_kms_key.redshift.arn

  automated_snapshot_retention_period = 7
  preferred_maintenance_window        = "sun:04:30-sun:05:30"

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-cluster-final-snapshot"

  tags = merge(local.common_tags, { name = "${local.name_prefix}-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_redshift_snapshot_schedule" "every_12_hours" {
  identifier  = "${local.name_prefix}-snapshot-schedule-12h"
  description = "Automated snapshot schedule firing every 12 hours"
  definitions = ["rate(12 hours)"]

  tags = merge(local.common_tags, { name = "${local.name_prefix}-snapshot-schedule-12h" })
}

resource "aws_redshift_snapshot_schedule_association" "main" {
  cluster_identifier  = aws_redshift_cluster.main.cluster_identifier
  schedule_identifier = aws_redshift_snapshot_schedule.every_12_hours.identifier
}

output "redshift_cluster_endpoint" {
  description = "Connection endpoint (address and port) of the Redshift cluster"
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret storing the Redshift admin credentials"
  value       = aws_redshift_cluster.main.master_password_secret_arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Non-infrastructure environment name used for resource tagging."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  name_prefix          = "redshift-${var.environment}"
  vpc_cidr             = "10.0.0.0/16"
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.20.0/24"]
  master_username      = "redshiftadmin"
  database_name        = "analyticsdb"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "redshift-data-platform"
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-subnet-${count.index + 1}" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-route-table" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# S3 gateway endpoint so the cluster in the private subnets can reach the
# staging bucket for COPY/UNLOAD without a NAT gateway or internet gateway.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-s3-gateway-endpoint" })
}

# -----------------------------------------------------------------------------
# KMS customer managed key
# -----------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Customer managed key for Redshift encryption at rest, S3 staging data, and secret encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms-key" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# S3 staging bucket for COPY/UNLOAD
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "staging" {
  bucket = "${local.name_prefix}-data-staging-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-data-staging" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "staging" {
  bucket = aws_s3_bucket.staging.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "staging" {
  bucket = aws_s3_bucket.staging.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.redshift.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "staging" {
  bucket = aws_s3_bucket.staging.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# IAM role for the Redshift cluster
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "redshift_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "redshift" {
  name               = "${local.name_prefix}-cluster-role"
  description        = "Role assumed by the Redshift cluster for S3 COPY/UNLOAD access"
  assume_role_policy = data.aws_iam_policy_document.redshift_assume_role.json

  tags = local.common_tags
}

# Least-privilege inline policy: read-only access scoped to the staging bucket.
data "aws_iam_policy_document" "redshift_s3_access" {
  statement {
    sid       = "ListStagingBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.staging.arn]
  }

  statement {
    sid       = "ReadStagingObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.staging.arn}/*"]
  }
}

resource "aws_iam_role_policy" "redshift_s3_access" {
  name   = "${local.name_prefix}-s3-access"
  role   = aws_iam_role.redshift.name
  policy = data.aws_iam_policy_document.redshift_s3_access.json
}

# Managed policy (attached via aws_iam_role_policy_attachment) granting the KMS
# permissions required to read/write SSE-KMS encrypted objects in the staging
# bucket from the cluster.
data "aws_iam_policy_document" "redshift_kms_access" {
  statement {
    sid    = "UseRedshiftKmsKeyForStaging"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.redshift.arn]
  }
}

resource "aws_iam_policy" "redshift_kms_access" {
  name        = "${local.name_prefix}-kms-access"
  description = "KMS decrypt and generate-data-key on the Redshift KMS key for SSE-KMS staging data"
  policy      = data.aws_iam_policy_document.redshift_kms_access.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "redshift_kms_access" {
  role       = aws_iam_role.redshift.name
  policy_arn = aws_iam_policy.redshift_kms_access.arn
}

# -----------------------------------------------------------------------------
# Redshift master credentials
# -----------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}-master-credentials"
  description = "Master credentials for the Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.key_id

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# -----------------------------------------------------------------------------
# Redshift cluster
# -----------------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-sg"
  description = "Restrict access to the Redshift cluster to the VPC on the Redshift port"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound access for S3 via the gateway VPC endpoint"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-sg" })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Private subnets across two AZs for the Redshift cluster"
  subnet_ids  = [aws_subnet.private[0].id, aws_subnet.private[1].id]

  tags = local.common_tags
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "${local.name_prefix}-cluster"
  database_name      = local.database_name
  master_username    = local.master_username
  master_password    = random_password.redshift_master.result

  node_type       = "ra3.xlplus"
  cluster_type    = "multi-node"
  number_of_nodes = 2

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = false
  enhanced_vpc_routing      = true

  encrypted  = true
  kms_key_id = aws_kms_key.redshift.arn

  # Associate the IAM role with the cluster so it can COPY/UNLOAD from S3.
  iam_roles = [aws_iam_role.redshift.arn]

  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-cluster-final-snapshot"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cluster" })

  depends_on = [
    aws_secretsmanager_secret_version.redshift_master,
    aws_iam_role_policy.redshift_s3_access,
    aws_iam_role_policy_attachment.redshift_kms_access,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  function_name = "example_lambda"
}

# -----------------------------------------------------------------------------
# IAM execution role for the Lambda function
# -----------------------------------------------------------------------------
resource "aws_iam_role" "example_lambda_exec" {
  name = "example_lambda_exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example_lambda_basic_execution" {
  role       = aws_iam_role.example_lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# -----------------------------------------------------------------------------
# CloudWatch log group with Terraform-managed retention
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "example_lambda" {
  name              = "/aws/lambda/${local.function_name}"
  retention_in_days = 14
}

# -----------------------------------------------------------------------------
# Lambda deployment package built inline (no external artifacts)
# -----------------------------------------------------------------------------
data "archive_file" "example_lambda_package" {
  type        = "zip"
  output_path = "${path.module}/build/${local.function_name}_payload.zip"

  source {
    filename = "index.py"
    content  = <<-EOT
      import json

      def lambda_handler(event, context):
          return {
              "statusCode": 200,
              "headers": {"Content-Type": "application/json"},
              "body": json.dumps({"message": "Hello from example_lambda!"}),
          }
      EOT
  }
}

# -----------------------------------------------------------------------------
# Lambda function (not VPC-attached)
# -----------------------------------------------------------------------------
resource "aws_lambda_function" "example_lambda" {
  function_name = local.function_name
  description   = "Example Lambda function exposed via an IAM-authenticated function URL."

  role          = aws_iam_role.example_lambda_exec.arn
  handler       = "index.lambda_handler"
  runtime       = "python3.12"
  architectures = ["arm64"]

  filename         = data.archive_file.example_lambda_package.output_path
  source_code_hash = data.archive_file.example_lambda_package.output_base64sha256

  memory_size = 256
  timeout     = 10

  depends_on = [
    aws_iam_role_policy_attachment.example_lambda_basic_execution,
    aws_cloudwatch_log_group.example_lambda,
  ]
}

# -----------------------------------------------------------------------------
# Lambda function URL (AWS_IAM authorization, not anonymous)
# -----------------------------------------------------------------------------
resource "aws_lambda_function_url" "example_lambda" {
  function_name      = aws_lambda_function.example_lambda.function_name
  authorization_type = "AWS_IAM"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "example_lambda_function_url" {
  description = "IAM-authenticated function URL endpoint for example_lambda."
  value       = aws_lambda_function_url.example_lambda.function_url
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  layer_name = "payload_layer"
}

resource "aws_lambda_layer_version" "payload_layer" {
  filename                 = "lambda_layer_payload.zip"
  layer_name               = local.layer_name
  description              = "Shared runtime dependencies for Python 3.12 Lambda functions, packaged from lambda_layer_payload.zip."
  compatible_runtimes      = ["python3.12"]
  compatible_architectures = ["x86_64"]
  source_code_hash         = try(filebase64sha256("lambda_layer_payload.zip"), null)
  license_info             = "MIT"

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  function_name = "lambda_js_function"

  lambda_handler_source = <<-EOT
    "use strict";

    exports.handler = async (event) => {
      console.log("Received event:", JSON.stringify(event));

      return {
        statusCode: 200,
        body: JSON.stringify({ message: "Hello from lambda.js" })
      };
    };
  EOT
}

data "archive_file" "lambda_zip" {
  type                    = "zip"
  source_content          = local.lambda_handler_source
  source_content_filename = "lambda.js"
  output_path             = "lambda.zip"
}

resource "aws_iam_role" "lambda_exec" {
  name = "${local.function_name}_exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${aws_lambda_function.main.function_name}"
  retention_in_days = 14
}

resource "aws_lambda_function" "main" {
  function_name    = local.function_name
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda.handler"
  runtime          = "nodejs22.x"
  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  memory_size      = 128
  timeout          = 10

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution
  ]
}

output "lambda_function_name" {
  description = "Name of the Lambda function."
  value       = aws_lambda_function.main.function_name
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function."
  value       = aws_lambda_function.main.arn
}

output "lambda_invoke_arn" {
  description = "Invoke ARN of the Lambda function."
  value       = aws_lambda_function.main.invoke_arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

variable "table_name" {
  description = "Name of the DynamoDB table that Contributor Insights will monitor."
  type        = string
  default     = "app-data"
}

variable "tags" {
  description = "Tags applied consistently to every taggable resource."
  type        = map(string)
  default     = {}
}

locals {
  gsi_name = "gsi-main-index"
}

resource "aws_kms_key" "dynamodb" {
  description             = "Customer managed key used to encrypt the DynamoDB table at rest."
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "main" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "gsi_pk"
    type = "S"
  }

  global_secondary_index {
    name            = local.gsi_name
    hash_key        = "gsi_pk"
    projection_type = "ALL"
  }

  ttl {
    enabled        = true
    attribute_name = "expiry_time"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb.arn
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Note: DynamoDB Contributor Insights resources cannot be tagged and do not
# expose ARNs through the AWS API, so the shared tags are applied to every
# taggable resource (table and KMS key, plus provider default_tags) and each
# Contributor Insights identifier is exported as an output below.

resource "aws_dynamodb_contributor_insights" "table" {
  table_name = aws_dynamodb_table.main.name
}

resource "aws_dynamodb_contributor_insights" "gsi" {
  table_name = aws_dynamodb_table.main.name
  index_name = local.gsi_name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table."
  value       = aws_dynamodb_table.main.arn
}

output "dynamodb_table_id" {
  description = "ID (name) of the DynamoDB table."
  value       = aws_dynamodb_table.main.id
}

output "table_contributor_insights_id" {
  description = "ID of the Contributor Insights resource enabled on the base table."
  value       = aws_dynamodb_contributor_insights.table.id
}

output "gsi_contributor_insights_id" {
  description = "ID of the Contributor Insights resource enabled on the global secondary index."
  value       = aws_dynamodb_contributor_insights.gsi.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag applied to all resources"
  type        = string
  default     = "dev"
}

locals {
  table_name = "app-data-table"
}

resource "aws_dynamodb_table" "main" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  tags = {
    Name        = local.table_name
    environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table_item" "main" {
  table_name = aws_dynamodb_table.main.name
  hash_key   = aws_dynamodb_table.main.hash_key

  item = jsonencode({
    id = {
      S = "item-001"
    }
    name = {
      S = "example-item"
    }
    description = {
      S = "Demo record provisioned by Terraform"
    }
    active = {
      BOOL = true
    }
    visit_count = {
      N = "42"
    }
    created_at = {
      S = "2025-01-01T00:00:00Z"
    }
  })

  depends_on = [aws_dynamodb_table.main]
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  value       = aws_dynamodb_table.main.name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table"
  value       = aws_dynamodb_table.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

variable "environment" {
  description = "Environment label applied to all resources via tags."
  type        = string
  default     = "production"

  validation {
    condition     = can(regex("^[a-z0-9-]+$", var.environment))
    error_message = "Environment must contain only lowercase letters, numbers, and hyphens."
  }
}

variable "dax_subnet_group_name" {
  description = "Name of the DAX subnet group. Must satisfy DAX naming rules (lowercase alphanumeric and hyphens only, no underscores)."
  type        = string
  default     = "dax-subnet-group-main"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{0,49}$", var.dax_subnet_group_name))
    error_message = "DAX subnet group name must start with a lowercase letter, contain only lowercase alphanumeric characters and hyphens (no underscores), and be 50 characters or fewer."
  }
}

variable "dax_private_subnets" {
  description = "Map of private subnets for DAX nodes. Each entry defines a CIDR within the VPC and an index into the available AZ list."
  type = map(object({
    cidr_block = string
    az_index   = number
  }))
  default = {
    a = {
      cidr_block = "10.0.1.0/24"
      az_index   = 0
    }
    b = {
      cidr_block = "10.0.2.0/24"
      az_index   = 1
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "dax-${var.environment}"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "dax_private" {
  for_each = var.dax_private_subnets

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value.cidr_block
  availability_zone       = data.aws_availability_zones.available.names[each.value.az_index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-${each.key}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dax_subnet_group" "main" {
  name        = var.dax_subnet_group_name
  description = "Private subnet group for DAX cluster nodes in ${var.environment}"
  subnet_ids  = [for subnet in aws_subnet.dax_private : subnet.id]

  lifecycle {
    prevent_destroy = true
  }
}

output "dax_subnet_group_name" {
  description = "Name of the DAX subnet group."
  value       = aws_dax_subnet_group.main.name
}

output "dax_private_subnet_ids" {
  description = "IDs of the private subnets backing the DAX subnet group."
  value       = [for subnet in aws_subnet.dax_private : subnet.id]
}

# =============================================================================
# SageMaker Studio Domain + Space - Greenfield, VPC-only, CMK-encrypted
# =============================================================================
# - Dedicated VPC with two private subnets in distinct AZs (AZs via data source)
# - No internet path: VpcOnly networking (domain-level), no IGW/NAT,
#   VPC endpoints (S3 gateway + interface endpoints) for AWS service access
# - Customer-managed KMS key for the domain home-directory EFS, domain volumes
#   and S3 artifacts
# - Dedicated, fully-private S3 artifacts bucket (block all public access,
#   SSE-KMS, versioning)
# - Least-privilege SageMaker execution role
# =============================================================================

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Non-infrastructure variables (all defaulted, so `terraform apply` is
# non-interactive)
# -----------------------------------------------------------------------------
variable "resource_name_prefix" {
  description = "Short lowercase prefix applied to all resource names."
  type        = string
  default     = "sm"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,18}$", var.resource_name_prefix))
    error_message = "resource_name_prefix must be 2-19 lowercase letters, digits or hyphens and must start with a letter."
  }
}

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{0,18}$", var.environment))
    error_message = "environment must be lowercase letters, digits or hyphens."
  }
}

# -----------------------------------------------------------------------------
# Static, well-known lookups only (no discovery of pre-existing infrastructure)
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.resource_name_prefix}-${var.environment}"

  vpc_cidr = "10.0.0.0/16"

  # SageMaker entity names only allow alphanumerics and hyphens.
  sagemaker_space_name = "ml-workspace"

  interface_endpoint_service_names = [
    "com.amazonaws.${data.aws_region.current.name}.sagemaker.api",
    "com.amazonaws.${data.aws_region.current.name}.sagemaker.runtime",
    "com.amazonaws.${data.aws_region.current.name}.ecr.api",
    "com.amazonaws.${data.aws_region.current.name}.ecr.dkr",
    "com.amazonaws.${data.aws_region.current.name}.logs",
    "com.amazonaws.${data.aws_region.current.name}.monitoring",
    "com.amazonaws.${data.aws_region.current.name}.kms",
    "com.amazonaws.${data.aws_region.current.name}.sts",
  ]

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = var.resource_name_prefix
  }
}

# -----------------------------------------------------------------------------
# Network foundation: VPC + two private subnets in distinct AZs
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index}"
    Tier = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security groups: SageMaker apps and VPC endpoints (no 0.0.0.0/0 ingress)
# -----------------------------------------------------------------------------
resource "aws_security_group" "sagemaker" {
  name        = "${local.name_prefix}-sagemaker-sg"
  description = "SageMaker domain and space app traffic restricted to the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS (2049) from the VPC CIDR for the domain-managed home EFS"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTPS (443) from the VPC CIDR for VPC endpoint access"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "App-to-app communication between SageMaker apps sharing this security group"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "All egress restricted to VPC-internal destinations (VPC endpoints, home EFS)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-sg"
  })
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpc-endpoint-sg"
  description = "Interface VPC endpoints reachable only from inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All egress restricted to VPC-internal destinations"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-endpoint-sg"
  })
}

# -----------------------------------------------------------------------------
# VPC endpoints: private connectivity for SageMaker apps (no internet path)
# -----------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-gateway-endpoint"
  })
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(local.interface_endpoint_service_names)

  vpc_id              = aws_vpc.main.id
  service_name        = each.value
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-endpoint-${each.key}"
  })
}

# -----------------------------------------------------------------------------
# Customer-managed KMS key for SageMaker storage (domain home-directory EFS,
# domain volumes and S3 artifacts)
# -----------------------------------------------------------------------------
resource "aws_kms_key" "sagemaker" {
  description             = "Customer managed key for SageMaker home-directory EFS, domain volumes and S3 artifacts"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMDelegationForAccount"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowSageMakerService"
        Effect    = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey",
          "kms:ReEncrypt*",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-kms"
  })
}

resource "aws_kms_alias" "sagemaker" {
  name          = "alias/${local.name_prefix}-sagemaker"
  target_key_id = aws_kms_key.sagemaker.key_id
}

# -----------------------------------------------------------------------------
# Private S3 bucket for SageMaker artifacts
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts" {
  bucket = "${local.name_prefix}-sagemaker-artifacts-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-artifacts"
  })
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sagemaker.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# SageMaker execution role (trusted by sagemaker.amazonaws.com) with
# least-privilege permissions
# -----------------------------------------------------------------------------
resource "aws_iam_role" "sagemaker_execution" {
  name = "${local.name_prefix}-sagemaker-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-execution-role"
  })
}

resource "aws_iam_role_policy" "sagemaker_execution" {
  name = "sagemaker-execution-least-privilege"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ArtifactAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*",
        ]
      },
      {
        Sid    = "CloudWatchLogsForSageMaker"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*",
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*:log-stream:*",
        ]
      },
      {
        Sid      = "ECRGetAuthorizationToken"
        Effect   = "Allow"
        Action   = "ecr:GetAuthorizationToken"
        Resource = "*"
      },
      {
        Sid    = "ECRPullImages"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:ecr:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:repository/*",
        ]
      },
    ]
  })
}

resource "aws_iam_policy" "sagemaker_storage_keys" {
  name        = "${local.name_prefix}-sagemaker-storage-keys"
  description = "KMS data key usage for SageMaker storage (home EFS and S3 artifacts)"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KmsDataKeyUsage"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
        ]
        Resource = [
          aws_kms_key.sagemaker.arn,
        ]
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-storage-keys"
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_storage_keys" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_storage_keys.arn
}

# -----------------------------------------------------------------------------
# SageMaker Studio domain: IAM auth, VPC-only networking, CMK-encrypted
# storage. Network isolation is enforced by app_network_access_type = "VpcOnly"
# together with the private-subnet topology (no internet gateway, no NAT
# gateway, AWS service access only via VPC endpoints).
# -----------------------------------------------------------------------------
resource "aws_sagemaker_domain" "main" {
  domain_name = "${local.name_prefix}-domain"
  auth_mode   = "IAM"

  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  app_network_access_type = "VpcOnly"

  # Encrypts the domain home EFS file system and domain volumes with the CMK
  kms_key_id = aws_kms_key.sagemaker.arn

  default_user_settings {
    execution_role  = aws_iam_role.sagemaker_execution.arn
    security_groups = [aws_security_group.sagemaker.id]

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "system"
      }
    }
  }

  retention_policy {
    home_efs_file_system = "Retain"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-domain"
  })
}

# -----------------------------------------------------------------------------
# Default user profile for the domain (owner of the space below)
# -----------------------------------------------------------------------------
resource "aws_sagemaker_user_profile" "default" {
  domain_id         = aws_sagemaker_domain.main.id
  user_profile_name = "default-user"

  user_settings {
    execution_role  = aws_iam_role.sagemaker_execution.arn
    security_groups = [aws_security_group.sagemaker.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-default-user"
  })
}

# -----------------------------------------------------------------------------
# SageMaker space: JupyterServer app with EBS-backed space storage (the only
# storage mechanism the provider supports for spaces; the app's EBS volume is
# encrypted by the SageMaker service, while the domain's home-directory EFS
# is encrypted with the CMK via aws_sagemaker_domain.main.kms_key_id).
# Network access is inherited from the domain (VpcOnly) and the app security
# group only permits traffic inside the VPC, so notebooks have no public
# internet path.
# -----------------------------------------------------------------------------
resource "aws_sagemaker_space" "ml_workspace" {
  domain_id  = aws_sagemaker_domain.main.id
  space_name = local.sagemaker_space_name

  ownership_settings {
    owner_user_profile_name = aws_sagemaker_user_profile.default.user_profile_name
  }

  space_sharing_settings {
    sharing_type = "Private"
  }

  space_settings {
    app_type = "JupyterServer"

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "system"
      }
    }

    space_storage_settings {
      ebs_storage_settings {
        ebs_volume_size_in_gb = 5
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-space-${local.sagemaker_space_name}"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "sagemaker_domain_id" {
  description = "ID of the SageMaker Studio domain."
  value       = aws_sagemaker_domain.main.id
}

output "sagemaker_domain_arn" {
  description = "ARN of the SageMaker Studio domain."
  value       = aws_sagemaker_domain.main.arn
}

output "sagemaker_space_arn" {
  description = "ARN of the SageMaker space."
  value       = aws_sagemaker_space.ml_workspace.arn
}

output "sagemaker_artifacts_bucket" {
  description = "Name of the private S3 bucket holding SageMaker artifacts."
  value       = aws_s3_bucket.artifacts.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "sagemaker_image" {
  description = "AWS-managed SageMaker built-in kmeans algorithm container image (us-east-1). Overridable, but defaults to a working value so apply runs unattended."
  type        = string
  default     = "382416733822.dkr.ecr.us-east-1.amazonaws.com/kmeans:1"
}

variable "tags" {
  description = "Tags applied to all taggable resources. Contains no secrets or environment-specific values."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Component = "sagemaker-kmeans-model"
  }
}

resource "aws_iam_role" "sagemaker_model_execution_role" {
  name = "sagemaker-kmeans-model-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "sagemaker_model_execution_policy" {
  name = "sagemaker-kmeans-model-execution-policy"
  role = aws_iam_role.sagemaker_model_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SageMakerECRImagePull"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = "*"
      },
      {
        Sid    = "SageMakerCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = "arn:aws:logs:*:*:log-group:/aws/sagemaker/*"
      },
      {
        Sid    = "SageMakerModelArtifactsRead"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::*",
          "arn:aws:s3:::*/*"
        ]
      }
    ]
  })
}

resource "aws_sagemaker_model" "kmeans_model" {
  execution_role_arn       = aws_iam_role.sagemaker_model_execution_role.arn
  enable_network_isolation = true

  primary_container {
    image = var.sagemaker_image
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "sagemaker_model_name" {
  description = "Name of the SageMaker kmeans model."
  value       = aws_sagemaker_model.kmeans_model.name
}

output "sagemaker_model_arn" {
  description = "ARN of the SageMaker kmeans model."
  value       = aws_sagemaker_model.kmeans_model.arn
}

output "sagemaker_execution_role_arn" {
  description = "ARN of the SageMaker model execution role."
  value       = aws_iam_role.sagemaker_model_execution_role.arn
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "human_task_ui_name" {
  description = "Deterministic kebab-case name for the SageMaker Human Task UI."
  type        = string
  default     = "test-human-task-ui"
}

variable "tags" {
  description = "Standard tags applied to the SageMaker Human Task UI."
  type        = map(string)
  default = {
    ManagedBy   = "Terraform"
    Environment = "test"
  }
}

locals {
  tags = merge(
    var.tags,
    {
      Name = var.human_task_ui_name
    }
  )
}

resource "aws_sagemaker_human_task_ui" "test_ui" {
  human_task_ui_name = var.human_task_ui_name

  ui_template {
    content = <<-EOT
      <h1>TEST</h1>
    EOT
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "human_task_ui_arn" {
  description = "ARN of the SageMaker Human Task UI, for reference by downstream resources such as flow definitions."
  value       = aws_sagemaker_human_task_ui.test_ui.arn
}

output "human_task_ui_id" {
  description = "ID of the SageMaker Human Task UI."
  value       = aws_sagemaker_human_task_ui.test_ui.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (all with defaults so terraform apply runs unattended)
###############################################################################

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "ssh_allowed_cidr" {
  description = "CIDR block permitted to open SSH (tcp/22) sessions to the instance."
  type        = string
  default     = "10.0.0.0/8"

  validation {
    condition     = var.ssh_allowed_cidr != "0.0.0.0/0"
    error_message = "SSH access must be restricted to a private management CIDR, never 0.0.0.0/0."
  }
}

variable "instance_type" {
  description = "EC2 instance type; must provide at least 4 vCPUs to satisfy the CPU options (2 cores x 2 threads per core)."
  type        = string
  default     = "t3.xlarge"
}

variable "root_volume_size" {
  description = "Size (GiB) of the encrypted gp3 root EBS volume."
  type        = number
  default     = 20
}

variable "project_name" {
  description = "Project name used for snake_case resource naming and the Project tag."
  type        = string
  default     = "amzn2_cpu_optimized"
}

variable "environment" {
  description = "Environment classification applied as the Environment tag."
  type        = string
  default     = "production"
}

variable "owner" {
  description = "Owning team applied as the Owner tag."
  type        = string
  default     = "platform_engineering"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (pure static lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "example" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

###############################################################################
# Networking: dedicated VPC, public subnet, IGW, and routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_public_subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_internet_gateway"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_public_route_table"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security group: SSH (tcp/22) restricted to private management CIDR
###############################################################################

resource "aws_security_group" "ssh_access" {
  name        = "${var.project_name}_ssh_access_sg"
  description = "Allow inbound SSH from the restricted management CIDR and permit all outbound traffic."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH (tcp/22) from the restricted management CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.ssh_allowed_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_ssh_access_sg"
  })
}

###############################################################################
# SSH key material: generated, registered, stored in Secrets Manager
###############################################################################

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "main" {
  key_name   = "${var.project_name}_key_pair"
  public_key = tls_private_key.main.public_key_openssh

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_key_pair"
  })
}

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name        = "${var.project_name}/ssh/private_key"
  description = "Private key material for the ${var.project_name} EC2 key pair."

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_ssh_private_key_secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "ssh_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.main.private_key_pem
}

###############################################################################
# IAM: least-privilege SSM management role and instance profile
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm_management" {
  name               = "${var.project_name}_ssm_management_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_ssm_management_role"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ssm_management.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm_management" {
  name = "${var.project_name}_ssm_management_profile"
  role = aws_iam_role.ssm_management.name

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_ssm_management_profile"
  })
}

###############################################################################
# EC2 instance: latest Amazon Linux 2, 2 cores x 2 threads per core (4 vCPUs)
###############################################################################

resource "aws_instance" "amazon_linux_2" {
  ami                         = data.aws_ami.example.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.ssh_access.id]
  key_name                    = aws_key_pair.main.key_name
  iam_instance_profile        = aws_iam_instance_profile.ssm_management.name
  associate_public_ip_address = true
  monitoring                  = true

  # Core requirement of the request: 2 cores x 2 threads per core = 4 vCPUs.
  cpu_options {
    core_count       = 2
    threads_per_core = 2
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "disabled"
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = var.root_volume_size
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_instance"
  })

  depends_on = [aws_iam_role_policy_attachment.ssm_managed_instance_core]
}

###############################################################################
# Outputs
###############################################################################

output "instance_id" {
  description = "ID of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.amazon_linux_2.id
}

output "instance_public_ip" {
  description = "Public IP address of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.amazon_linux_2.public_ip
}

output "ssh_private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the SSH private key."
  value       = aws_secretsmanager_secret.ssh_private_key.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  name_prefix = lower(var.environment)

  db_username = "dbadmin"
  db_name     = "appdb"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public"
    Tier = "public"
  })
}

resource "aws_subnet" "private_app" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-app"
    Tier = "application"
  })
}

resource "aws_subnet" "private_db" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.21.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-db"
    Tier = "database"
  })
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private_app" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-app-rt"
  })
}

resource "aws_route_table_association" "private_app" {
  subnet_id      = aws_subnet.private_app.id
  route_table_id = aws_route_table.private_app.id
}

resource "aws_route_table" "private_db" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-db-rt"
  })
}

resource "aws_route_table_association" "private_db" {
  subnet_id      = aws_subnet.private_db.id
  route_table_id = aws_route_table.private_db.id
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "webserver" {
  name        = "${local.name_prefix}-webserver-sg"
  description = "Web tier: allow HTTP/HTTPS from the internet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-webserver-sg"
  })
}

resource "aws_security_group" "app_server" {
  name        = "${local.name_prefix}-app-sg"
  description = "Application tier: allow port 8080 from the web tier security group only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application traffic from the webserver security group"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.webserver.id]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-sg"
  })
}

resource "aws_security_group" "database" {
  name        = "${local.name_prefix}-db-sg"
  description = "Database tier: allow MySQL 3306 from the application tier security group only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from the application server security group"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.app_server.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

# -----------------------------------------------------------------------------
# IAM
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2ToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "webserver" {
  name               = "${local.name_prefix}-webserver-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-webserver-role"
  })
}

resource "aws_iam_role_policy_attachment" "webserver_ssm" {
  role       = aws_iam_role.webserver.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "webserver" {
  name = "${local.name_prefix}-webserver-profile"
  role = aws_iam_role.webserver.name
}

resource "aws_iam_role" "app_server" {
  name               = "${local.name_prefix}-app-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-role"
  })
}

resource "aws_iam_role_policy_attachment" "app_server_ssm" {
  role       = aws_iam_role.app_server.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy_document" "app_server_db_secret_read" {
  statement {
    sid       = "ReadDatabaseSecret"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.db.arn]
  }
}

resource "aws_iam_role_policy" "app_server_db_secret" {
  name   = "${local.name_prefix}-read-db-secret"
  role   = aws_iam_role.app_server.name
  policy = data.aws_iam_policy_document.app_server_db_secret_read.json
}

resource "aws_iam_instance_profile" "app_server" {
  name = "${local.name_prefix}-app-profile"
  role = aws_iam_role.app_server.name
}

# -----------------------------------------------------------------------------
# Compute
# -----------------------------------------------------------------------------

resource "aws_instance" "webserver" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.webserver.id]
  iam_instance_profile        = aws_iam_instance_profile.webserver.name

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -euxo pipefail
    dnf update -y
    dnf install -y httpd
    systemctl enable --now httpd
    echo "<html><body><h1>Web server (${local.name_prefix} environment)</h1></body></html>" > /var/www/html/index.html
  EOF

  depends_on = [aws_route_table_association.public]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-webserver"
    Tier = "public"
  })
}

resource "aws_instance" "app_server" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.private_app.id
  associate_public_ip_address = false
  vpc_security_group_ids      = [aws_security_group.app_server.id]
  iam_instance_profile        = aws_iam_instance_profile.app_server.name

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -euxo pipefail
    dnf update -y
    dnf install -y python3
    mkdir -p /opt/app
    echo "Application server is running" > /opt/app/index.html
    cat > /etc/systemd/system/app.service <<'UNIT'
    [Unit]
    Description=Demo application server (port 8080)
    After=network.target

    [Service]
    ExecStart=/usr/bin/python3 -m http.server 8080 --directory /opt/app
    Restart=always

    [Install]
    WantedBy=multi-user.target
    UNIT
    systemctl daemon-reload
    systemctl enable --now app.service
  EOF

  depends_on = [aws_route_table_association.private_app, aws_nat_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-server"
    Tier = "application"
  })
}

# -----------------------------------------------------------------------------
# Database
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "database" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.private_app.id, aws_subnet.private_db.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "random_password" "db" {
  length           = 24
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "random_id" "db_final_snapshot" {
  byte_length = 4
}

resource "aws_db_instance" "database" {
  identifier                 = "${local.name_prefix}-mysql"
  engine                     = "mysql"
  engine_version             = "8.0"
  instance_class             = "db.t3.micro"
  allocated_storage          = 20
  max_allocated_storage      = 100
  storage_type               = "gp3"
  db_name                    = local.db_name
  username                   = local.db_username
  password                   = random_password.db.result
  port                       = 3306
  db_subnet_group_name       = aws_db_subnet_group.database.name
  vpc_security_group_ids     = [aws_security_group.database.id]
  publicly_accessible        = false
  multi_az                   = false
  storage_encrypted          = true
  deletion_protection        = true
  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  skip_final_snapshot        = false
  final_snapshot_identifier  = "${local.name_prefix}-mysql-final-${random_id.db_final_snapshot.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql"
    Tier = "database"
  })
}

# -----------------------------------------------------------------------------
# Secrets
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "db" {
  name        = "${local.name_prefix}-db-credentials"
  description = "Master credentials for the ${local.name_prefix} RDS MySQL instance"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db.result
    engine   = "mysql"
    host     = aws_db_instance.database.address
    port     = aws_db_instance.database.port
    dbname   = local.db_name
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "webserver_public_ip" {
  description = "Public IP address of the webserver instance."
  value       = aws_instance.webserver.public_ip
}

output "app_server_private_ip" {
  description = "Private IP address of the application server instance."
  value       = aws_instance.app_server.private_ip
}

output "rds_endpoint" {
  description = "Connection endpoint address of the RDS MySQL instance."
  value       = aws_db_instance.database.address
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static provider metadata used for AZ selection
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "redis-auth"

  common_tags = {
    Project   = "elasticache-redis-user-auth"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking (greenfield VPC + private cache subnets in 2 AZs)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b" })
}

resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.name_prefix}-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-subnet-group" })
}

# -----------------------------------------------------------------------------
# Security group: Redis reachable only from within the VPC
# -----------------------------------------------------------------------------

resource "aws_security_group" "redis" {
  name        = "${local.name_prefix}-cache-sg"
  description = "Restrict Redis access to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis (TCP 6379) from within the VPC"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cache-sg" })
}

# -----------------------------------------------------------------------------
# Redis user credential: generated password + Secrets Manager storage
# -----------------------------------------------------------------------------

resource "random_password" "redis_auth" {
  length           = 36
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redis_auth" {
  name        = "elasticache/${local.name_prefix}/user-credentials"
  description = "ElastiCache Redis RBAC user authentication credentials"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-user-credentials" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redis_auth" {
  secret_id = aws_secretsmanager_secret.redis_auth.id
  secret_string = jsonencode({
    username = aws_elasticache_user.redis_auth.user_name
    password = random_password.redis_auth.result
    engine   = "redis"
    host     = aws_elasticache_replication_group.redis.primary_endpoint_address
    port     = aws_elasticache_replication_group.redis.port
    ssl      = true
  })
}

# -----------------------------------------------------------------------------
# ElastiCache RBAC user (least-privilege ACL) and user group
# -----------------------------------------------------------------------------

resource "aws_elasticache_user" "redis_auth" {
  user_id              = "${local.name_prefix}-user"
  user_name            = "appuser"
  engine               = "redis"
  access_string        = "on ~app:* -@all +@read +@write"
  no_password_required = false
  passwords            = [random_password.redis_auth.result]
}

resource "aws_elasticache_user_group" "redis_users" {
  user_group_id = "${local.name_prefix}-users"
  engine        = "redis"
  user_ids      = [aws_elasticache_user.redis_auth.user_id]
}

# -----------------------------------------------------------------------------
# Replication group enforcing user-group (RBAC) authentication
# -----------------------------------------------------------------------------

resource "aws_elasticache_replication_group" "redis" {
  replication_group_id = "${local.name_prefix}-rg"
  description          = "Redis replication group enforcing user-group (RBAC) password authentication"

  engine               = "redis"
  engine_version       = "7.0"
  node_type            = "cache.t3.small"
  parameter_group_name = "default.redis7"
  port                 = 6379

  num_node_groups         = 1
  replicas_per_node_group = 1

  automatic_failover_enabled = true
  multi_az_enabled           = true

  at_rest_encryption_enabled = true
  transit_encryption_enabled = true

  subnet_group_name  = aws_elasticache_subnet_group.main.name
  security_group_ids = [aws_security_group.redis.id]

  user_group_ids = [aws_elasticache_user_group.redis_users.id]

  snapshot_retention_limit = 7
  snapshot_window          = "03:00-05:00"
  maintenance_window       = "sun:05:30-sun:06:30"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rg" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "redis_primary_endpoint_address" {
  description = "Primary endpoint address of the Redis replication group"
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
}

output "redis_primary_endpoint_port" {
  description = "Primary endpoint port of the Redis replication group"
  value       = aws_elasticache_replication_group.redis.port
}

output "redis_auth_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the Redis user credentials (retrieve the password via the secret, never in plaintext)"
  value       = aws_secretsmanager_secret.redis_auth.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag applied to all resources (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

locals {
  table_name = "ExampleTableName"

  common_tags = {
    Name        = local.table_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_service_linked_role" "dynamodb_contributor_insights" {
  aws_service_name = "ddb.contributorinsights.amazonaws.com"
  description      = "Service-linked role required by DynamoDB Contributor Insights."
  tags             = local.common_tags
}

resource "aws_dynamodb_table" "example" {
  name         = local.table_name
  hash_key     = "Id"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "Id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_contributor_insights" "example" {
  table_name = aws_dynamodb_table.example.name

  depends_on = [aws_iam_service_linked_role.dynamodb_contributor_insights]
}

output "dynamodb_table_arn" {
  description = "ARN of the ExampleTableName DynamoDB table."
  value       = aws_dynamodb_table.example.arn
}

output "contributor_insights_name" {
  description = "Name of the Contributor Insights analysis on the base table."
  value       = aws_dynamodb_contributor_insights.example.id
}

output "service_linked_role_arn" {
  description = "ARN of the DynamoDB Contributor Insights service-linked role."
  value       = aws_iam_service_linked_role.dynamodb_contributor_insights.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-2"
}

locals {
  name_prefix = "msk-greenfield"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "msk_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-subnet-0"
  }
}

resource "aws_subnet" "msk_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-subnet-1"
  }
}

resource "aws_subnet" "msk_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-subnet-2"
  }
}

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}-broker-sg"
  description = "Restrict access to Kafka broker ports for the MSK cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client access over TLS"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka client access via SASL/IAM"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "ZooKeeper access"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Egress restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.name_prefix}-broker-sg"
  }
}

resource "aws_kms_key" "msk" {
  description             = "KMS key for MSK broker storage encryption at rest"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  tags = {
    Name = "${local.name_prefix}-key"
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/msk-greenfield"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.name_prefix}-cluster"
  retention_in_days = 30

  tags = {
    Name = "${local.name_prefix}-broker-logs"
  }
}

resource "aws_msk_cluster" "main" {
  cluster_name           = "msk-greenfield-cluster"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    az_distribution = "DEFAULT"

    client_subnets = [
      aws_subnet.msk_0.id,
      aws_subnet.msk_1.id,
      aws_subnet.msk_2.id,
    ]

    instance_type = "kafka.m5.large"

    security_groups = [
      aws_security_group.msk_brokers.id,
    ]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam = true
    }

    unauthenticated = false
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  enhanced_monitoring = "PER_BROKER"

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  tags = {
    Name = "msk-greenfield-cluster"
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_cloudwatch_log_group.msk_broker_logs]
}

output "msk_cluster_arn" {
  description = "The ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker endpoints for Kafka client configuration."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "msk_bootstrap_brokers_sasl_iam" {
  description = "SASL/IAM bootstrap broker endpoints for Kafka client configuration."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_zookeeper_connect_string" {
  description = "ZooKeeper connection string for the MSK cluster."
  value       = aws_msk_cluster.main.zookeeper_connect_string
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name applied to all resource tags."
  type        = string
  default     = "kafka-platform"
}

variable "environment" {
  description = "Environment name applied to all resource tags."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC hosting the MSK cluster."
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  root_arn   = "arn:${local.partition}:iam::${local.account_id}:root"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# MSK requires VPC DNS resolution and hostnames for bootstrap broker discovery.
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-${var.environment}-vpc"
    }
  )
}

# Three private subnets across three distinct AZs; broker count (3) is a
# multiple of the subnet count (3).
resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-${var.environment}-private-${count.index + 1}"
      Tier = "private"
    }
  )
}

# Dedicated security group for MSK broker nodes: ingress only on Kafka TLS
# port 9094 from the VPC CIDR, with explicit egress rules.
resource "aws_security_group" "msk_brokers" {
  name        = "${var.project_name}-${var.environment}-msk-brokers-sg"
  description = "Kafka broker nodes - TLS client ingress (9094) from VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client TLS connections from within the VPC"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS to AWS service endpoints"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All protocols to resources within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-${var.environment}-msk-brokers-sg"
    }
  )
}

# Customer-managed KMS key used for MSK encryption at rest.
resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK encryption at rest"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccountRootToAdministerKey"
        Effect    = "Allow"
        Principal = { AWS = local.root_arn }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowAccountRootToUseKey"
        Effect    = "Allow"
        Principal = { AWS = local.root_arn }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowMSKServiceToUseKey"
        Effect    = "Allow"
        Principal = { Service = "msk.amazonaws.com" }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*",
          "kms:CreateGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/msk-encryption-at-rest"
  target_key_id = aws_kms_key.msk.key_id
}

# Managed streaming cluster: 3 brokers across 3 subnets in 3 AZs, encrypted
# at rest with the customer-managed key and in transit with TLS.
resource "aws_msk_cluster" "encrypted_kafka" {
  cluster_name           = "${var.project_name}-${var.environment}-kafka"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      aws_subnet.private[0].id,
      aws_subnet.private[1].id,
      aws_subnet.private[2].id,
    ]
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.encrypted_kafka.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "Comma-separated list of TLS bootstrap broker endpoints for clients."
  value       = aws_msk_cluster.encrypted_kafka.bootstrap_brokers_tls
}

output "msk_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the cluster at rest."
  value       = aws_kms_key.msk.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource in this configuration."
  type        = string
  default     = "dev"
}

locals {
  name_prefix  = "msk_${var.environment}"
  cluster_name = "msk-${var.environment}"

  common_tags = {
    environment = var.environment
    component   = "msk"
    managed_by  = "terraform"
  }

  # Least-privilege resource patterns derived from the cluster ARN.
  # MSK IAM resource format:
  #   arn:aws:kafka:<region>:<account>:topic/<cluster-name>/<topic-pattern>/<cluster-uuid>
  #   arn:aws:kafka:<region>:<account>:group/<cluster-name>/<group-pattern>/<cluster-uuid>
  msk_topic_arn_pattern = replace(aws_msk_cluster.msk.arn, ":cluster/${local.cluster_name}/", ":topic/${local.cluster_name}/*/")
  msk_group_arn_pattern = replace(aws_msk_cluster.msk.arn, ":cluster/${local.cluster_name}/", ":group/${local.cluster_name}/*/")
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { name = "${local.name_prefix}_vpc" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "msk_private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { name = "${local.name_prefix}_private_subnet_${count.index + 1}" })
}

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}_brokers_sg"
  description = "MSK broker access restricted to the VPC: IAM listener (9098), TLS listener (9094), and inter-broker traffic from itself"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka clients over the IAM-authenticated listener (port 9098)"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka clients over the TLS listener (port 9094)"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "MSK inter-broker communication on the in-cluster listener (required between broker ENIs sharing this security group)"
    from_port   = 9093
    to_port     = 9093
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Allow all outbound traffic from brokers"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { name = "${local.name_prefix}_brokers_sg" })
}

# ---------------------------------------------------------------------------
# Encryption
# ---------------------------------------------------------------------------

resource "aws_kms_key" "msk" {
  description             = "Customer-managed key used for encryption at rest of the MSK cluster"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { name = "${local.name_prefix}_kms_key" })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Observability
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.cluster_name}/broker_logs"
  retention_in_days = 30

  tags = merge(local.common_tags, { name = "${local.name_prefix}_broker_logs" })
}

# ---------------------------------------------------------------------------
# MSK cluster (provisioned, 3 brokers across 3 AZs)
# ---------------------------------------------------------------------------

resource "aws_msk_cluster" "msk" {
  cluster_name           = local.cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.msk_private[*].id
    security_groups = [aws_security_group.msk_brokers.id]

    connectivity_info {
      public_access {
        type = "DISABLED"
      }
    }

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam   = true
      scram = false
    }

    tls {}

    unauthenticated = false
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }

      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  tags = merge(local.common_tags, { name = local.cluster_name })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM: least-privilege Kafka client access policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_client_access" {
  statement {
    sid       = "MSKClusterConnect"
    effect    = "Allow"
    actions   = ["kafka-cluster:Connect"]
    resources = [aws_msk_cluster.msk.arn]
  }

  statement {
    sid    = "MSKTopicReadWrite"
    effect = "Allow"
    actions = [
      "kafka-cluster:CreateTopic",
      "kafka-cluster:DescribeTopic",
      "kafka-cluster:AlterTopic",
      "kafka-cluster:WriteData",
      "kafka-cluster:ReadData",
    ]
    resources = [local.msk_topic_arn_pattern]
  }

  statement {
    sid    = "MSKConsumerGroupManage"
    effect = "Allow"
    actions = [
      "kafka-cluster:AlterGroup",
      "kafka-cluster:DescribeGroup",
    ]
    resources = [local.msk_group_arn_pattern]
  }
}

resource "aws_iam_policy" "msk_client_access" {
  name        = "${local.name_prefix}_client_access"
  description = "Least-privilege Kafka client access to the ${local.cluster_name} MSK cluster over IAM authentication"
  policy      = data.aws_iam_policy_document.msk_client_access.json

  tags = merge(local.common_tags, { name = "${local.name_prefix}_client_access" })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.msk.arn
}

output "msk_bootstrap_brokers_iam" {
  description = "Comma-separated bootstrap broker endpoints for IAM-authenticated clients (port 9098)."
  value       = aws_msk_cluster.msk.bootstrap_brokers_sasl_iam
}

output "msk_bootstrap_brokers_tls" {
  description = "Comma-separated bootstrap broker endpoints for TLS clients (port 9094)."
  value       = aws_msk_cluster.msk.bootstrap_brokers_tls
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data sources (pure local / static lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  region               = "us-east-1"
  account_id           = data.aws_caller_identity.current.account_id
  partition            = data.aws_partition.current.partition
  kafka_cluster_name   = "msk-kafka"
  msk_logs_bucket_name = "msk-logs-${local.account_id}"
  plugin_bucket_name   = "msk-connect-plugins-${local.account_id}"
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)

  tags = {
    Name = "msk-private-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "msk-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "msk_brokers" {
  name        = "msk-broker-sg"
  description = "Security group for MSK Kafka brokers"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "msk-broker-sg"
  }
}

resource "aws_security_group" "msk_connect_workers" {
  name        = "msk-connect-worker-sg"
  description = "Security group for MSK Connect worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "msk-connect-worker-sg"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "msk-vpc-endpoint-sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "msk-vpc-endpoint-sg"
  }
}

# Broker ingress: Kafka TLS (9094) restricted to the VPC CIDR
resource "aws_security_group_rule" "msk_brokers_ingress_from_vpc" {
  type              = "ingress"
  from_port         = 9094
  to_port           = 9094
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk_brokers.id
  description       = "Kafka TLS from within the VPC"
}

# Broker ingress: Kafka TLS (9094) sourced from the MSK Connect worker SG
resource "aws_security_group_rule" "msk_brokers_ingress_from_connect" {
  type                     = "ingress"
  from_port                = 9094
  to_port                  = 9094
  protocol                 = "tcp"
  security_group_id        = aws_security_group.msk_brokers.id
  source_security_group_id = aws_security_group.msk_connect_workers.id
  description              = "Kafka TLS from MSK Connect workers"
}

resource "aws_security_group_rule" "msk_brokers_egress_all" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.msk_brokers.id
  description       = "Outbound to AWS service endpoints (CloudWatch, Firehose, S3)"
}

# Connect worker egress: Kafka TLS (9094) to the broker security group
resource "aws_security_group_rule" "msk_connect_egress_to_brokers" {
  type                     = "egress"
  from_port                = 9094
  to_port                  = 9094
  protocol                 = "tcp"
  security_group_id        = aws_security_group.msk_connect_workers.id
  source_security_group_id = aws_security_group.msk_brokers.id
  description              = "Kafka TLS to MSK brokers"
}

resource "aws_security_group_rule" "msk_connect_egress_to_endpoints" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.msk_connect_workers.id
  source_security_group_id = aws_security_group.vpc_endpoints.id
  description              = "HTTPS to VPC interface endpoints"
}

resource "aws_security_group_rule" "msk_connect_egress_to_s3" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  prefix_list_ids   = [aws_vpc_endpoint.s3.prefix_list_id]
  security_group_id = aws_security_group.msk_connect_workers.id
  description       = "HTTPS to Amazon S3 via gateway endpoint"
}

resource "aws_security_group_rule" "msk_connect_egress_dns_udp" {
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "udp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk_connect_workers.id
  description       = "DNS to VPC resolver"
}

resource "aws_security_group_rule" "msk_connect_egress_dns_tcp" {
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk_connect_workers.id
  description       = "DNS over TCP to VPC resolver"
}

# -----------------------------------------------------------------------------
# VPC endpoints (private-subnet access to S3, CloudWatch Logs, Firehose)
# -----------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${local.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = {
    Name = "msk-s3-gateway-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "msk-cloudwatch-logs-endpoint"
  }
}

resource "aws_vpc_endpoint" "firehose" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.firehose"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "msk-firehose-endpoint"
  }
}

# -----------------------------------------------------------------------------
# KMS key for MSK encryption at rest
# -----------------------------------------------------------------------------

resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK cluster encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowMSKService"
        Effect    = "Allow"
        Principal = { Service = "kafka.amazonaws.com" }
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# CloudWatch log groups
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.kafka_cluster_name}/broker-logs"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_group" "msk_connect_logs" {
  name              = "/aws/kafkaconnect/${local.kafka_cluster_name}/worker-logs"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_group" "firehose_delivery_logs" {
  name              = "/aws/kinesisfirehose/${local.kafka_cluster_name}-firehose"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_stream" "firehose_delivery_logs" {
  name           = "delivery-errors"
  log_group_name = aws_cloudwatch_log_group.firehose_delivery_logs.name
}

# -----------------------------------------------------------------------------
# S3 log bucket (MSK broker logs + Firehose delivery destination)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_logs" {
  bucket = local.msk_logs_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# S3 plugin bucket + Debezium plugin artifact
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_connect_plugins" {
  bucket = local.plugin_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "msk_connect_plugins" {
  bucket = aws_s3_bucket.msk_connect_plugins.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_connect_plugins" {
  bucket = aws_s3_bucket.msk_connect_plugins.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# A local "debezium.zip" connector artifact must be shipped alongside this
# configuration; it is uploaded to the private plugin bucket below. The ETag
# is computed by the provider after upload, so no local file hashing is used.
resource "aws_s3_object" "debezium_plugin" {
  bucket       = aws_s3_bucket.msk_connect_plugins.id
  key          = "debezium.zip"
  source       = "debezium.zip"
  content_type = "application/zip"
}

# -----------------------------------------------------------------------------
# IAM: role used by MSK (kafka.amazonaws.com) to deliver broker logs
# -----------------------------------------------------------------------------

resource "aws_iam_role" "msk_log_delivery" {
  name = "msk-broker-log-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "kafka.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_log_delivery" {
  name = "msk-broker-log-delivery-policy"
  role = aws_iam_role.msk_log_delivery.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteBrokerLogsToCloudWatch"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.msk_broker_logs.arn,
          "${aws_cloudwatch_log_group.msk_broker_logs.arn}:log-stream:*"
        ]
      },
      {
        Sid    = "WriteBrokerLogsToFirehose"
        Effect = "Allow"
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch",
          "firehose:DescribeDeliveryStream"
        ]
        Resource = [
          aws_kinesis_firehose_delivery_stream.msk_broker_logs.arn
        ]
      },
      {
        Sid      = "ListLogBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.msk_logs.arn]
      },
      {
        Sid      = "PutBrokerLogsToS3"
        Effect   = "Allow"
        Action   = ["s3:PutObject"]
        Resource = ["${aws_s3_bucket.msk_logs.arn}/*"]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM: role used by Firehose (firehose.amazonaws.com) to deliver to S3
# -----------------------------------------------------------------------------

resource "aws_iam_role" "firehose_delivery" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "firehose.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_delivery" {
  name = "firehose-delivery-policy"
  role = aws_iam_role.firehose_delivery.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListDestinationBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.msk_logs.arn]
      },
      {
        Sid      = "WriteToDestinationBucket"
        Effect   = "Allow"
        Action   = ["s3:PutObject"]
        Resource = ["${aws_s3_bucket.msk_logs.arn}/*"]
      },
      {
        Sid    = "WriteDeliveryLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.firehose_delivery_logs.arn,
          "${aws_cloudwatch_log_group.firehose_delivery_logs.arn}:log-stream:*"
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Kinesis Firehose delivery stream
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "msk_broker_logs" {
  name        = "msk-broker-logs"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn            = aws_iam_role.firehose_delivery.arn
    bucket_arn          = aws_s3_bucket.msk_logs.arn
    prefix              = "msk/broker-logs/firehose/dt=!{timestamp:yyyy-MM-dd-HH}/"
    error_output_prefix = "msk/broker-logs/errors/!{firehose:error-output-type}/"
    buffering_size      = 5
    buffering_interval  = 300
    compression_format  = "GZIP"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_delivery_logs.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_delivery_logs.name
    }
  }

  depends_on = [aws_iam_role_policy.firehose_delivery]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# MSK cluster
# -----------------------------------------------------------------------------

resource "aws_msk_cluster" "kafka" {
  cluster_name           = local.kafka_cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }

      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }

      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_broker_logs.name
      }

      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs.id
        prefix  = "msk/broker-logs"
      }
    }
  }

  depends_on = [aws_iam_role_policy.msk_log_delivery]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# MSK Connect custom plugin (Debezium)
# -----------------------------------------------------------------------------

resource "aws_mskconnect_custom_plugin" "debezium" {
  name         = "debezium-custom-plugin"
  description  = "Debezium connector plugin"
  content_type = "ZIP"

  location {
    s3 {
      bucket_arn = aws_s3_bucket.msk_connect_plugins.arn
      file_key   = aws_s3_object.debezium_plugin.key
    }
  }
}

# -----------------------------------------------------------------------------
# MSK Connect worker configuration
# -----------------------------------------------------------------------------

resource "aws_mskconnect_worker_configuration" "debezium" {
  name        = "debezium-worker-configuration"
  description = "Worker configuration for the Debezium connector"

  properties_file_content = <<-EOT
  key.converter=org.apache.kafka.connect.json.JsonConverter
  value.converter=org.apache.kafka.connect.json.JsonConverter
  key.converter.schemas.enable=true
  value.converter.schemas.enable=true
  config.storage.replication.factor=3
  offset.storage.replication.factor=3
  status.storage.replication.factor=3
  EOT
}

# -----------------------------------------------------------------------------
# IAM: execution role for MSK Connect (kafkaconnect.amazonaws.com)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "msk_connect_exec" {
  name = "msk-connect-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "kafkaconnect.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_connect_exec" {
  name = "msk-connect-execution-policy"
  role = aws_iam_role.msk_connect_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListPluginBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.msk_connect_plugins.arn]
      },
      {
        Sid      = "ReadPluginArtifact"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.msk_connect_plugins.arn}/debezium.zip"]
      },
      {
        Sid    = "WriteWorkerLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.msk_connect_logs.arn,
          "${aws_cloudwatch_log_group.msk_connect_logs.arn}:log-stream:*"
        ]
      },
      {
        Sid    = "KafkaClusterAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
          "kafka-cluster:CreateTopic",
          "kafka-cluster:AlterTopic",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:DescribeTopicDynamicConfiguration",
          "kafka-cluster:WriteData",
          "kafka-cluster:ReadData"
        ]
        Resource = [
          aws_msk_cluster.kafka.arn,
          "arn:${local.partition}:kafka:${local.region}:${local.account_id}:topic/${local.kafka_cluster_name}/*"
        ]
      },
      {
        Sid    = "KafkaConsumerGroups"
        Effect = "Allow"
        Action = [
          "kafka-cluster:AlterGroup",
          "kafka-cluster:DescribeGroup"
        ]
        Resource = [
          "arn:${local.partition}:kafka:${local.region}:${local.account_id}:group/${local.kafka_cluster_name}/*"
        ]
      },
      {
        Sid      = "KafkaConnectApi"
        Effect   = "Allow"
        Action   = ["kafkaconnect:DescribeCustomPlugin"]
        Resource = [aws_mskconnect_custom_plugin.debezium.arn]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# MSK Connect connector
# -----------------------------------------------------------------------------

resource "aws_mskconnect_connector" "debezium" {
  name        = "debezium-connector"
  description = "Debezium source connector streaming into the MSK cluster"

  kafkaconnect_version = "3.3.1"

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.kafka.bootstrap_brokers_tls

      vpc {
        subnets         = aws_subnet.private[*].id
        security_groups = [aws_security_group.msk_connect_workers.id]
      }
    }
  }

  capacity {
    autoscaling {
      mcu_count        = 1
      min_worker_count = 1
      max_worker_count = 3

      scale_in_policy {
        cpu_utilization_percentage = 30
      }

      scale_out_policy {
        cpu_utilization_percentage = 70
      }
    }
  }

  # Placeholder Debezium source database settings - replace with real values.
  connector_configuration = {
    "connector.class"    = "io.debezium.connector.postgresql.PostgresConnector"
    "database.hostname"  = "source-db.internal"
    "database.port"      = "5432"
    "database.user"      = "debezium"
    "database.dbname"    = "sourcedb"
    "topic.prefix"       = "msk-source"
    "table.include.list" = "public.events"
    "snapshot.mode"      = "initial"
    "plugin.name"        = "pgoutput"
  }

  plugin {
    custom_plugin {
      arn      = aws_mskconnect_custom_plugin.debezium.arn
      revision = aws_mskconnect_custom_plugin.debezium.latest_revision
    }
  }

  worker_configuration {
    arn      = aws_mskconnect_worker_configuration.debezium.arn
    revision = aws_mskconnect_worker_configuration.debezium.latest_revision
  }

  service_execution_role_arn = aws_iam_role.msk_connect_exec.arn

  kafka_cluster_client_authentication {
    authentication_type = "NONE"
  }

  kafka_cluster_encryption_in_transit {
    encryption_type = "TLS"
  }

  log_delivery {
    worker_log_delivery {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_connect_logs.name
      }
    }
  }

  depends_on = [aws_iam_role_policy.msk_connect_exec]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster"
  value       = aws_msk_cluster.kafka.arn
}

output "msk_cluster_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker endpoints for the MSK cluster"
  value       = aws_msk_cluster.kafka.bootstrap_brokers_tls
}

output "msk_connect_connector_arn" {
  description = "ARN of the MSK Connect connector"
  value       = aws_mskconnect_connector.debezium.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (all with defaults so `terraform apply` runs unattended)
# -----------------------------------------------------------------------------

variable "project" {
  description = "Project name used for resource naming and consistent tagging."
  type        = string
  default     = "mysql"
}

variable "environment" {
  description = "Environment name used for resource naming and consistent tagging."
  type        = string
  default     = "prod"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC hosting the MySQL cluster."
  type        = string
  default     = "10.0.0.0/16"
}

variable "db_engine_version" {
  description = "MySQL engine version for the Multi-AZ DB cluster."
  type        = string
  default     = "8.0.35"
}

variable "db_instance_class" {
  description = "DB instance class for the cluster writer and readers."
  type        = string
  default     = "db.r6i.large"
}

variable "db_master_username" {
  description = "Master username for the MySQL cluster. The password is generated at apply time and stored in Secrets Manager."
  type        = string
  default     = "dbadmin"
}

variable "db_backup_retention_days" {
  description = "Automated backup retention period (days) for the MySQL cluster."
  type        = number
  default     = 14

  validation {
    condition     = var.db_backup_retention_days >= 7 && var.db_backup_retention_days <= 35
    error_message = "Backup retention must be between 7 and 35 days."
  }
}

locals {
  name_prefix = lower("${var.project}-${var.environment}")

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# One private subnet in each of three distinct AZs (resolved dynamically via
# the AZ data source so the cluster spans three AZs, e.g. us-east-1a, us-east-1b
# and us-east-1c).
resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 2)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_subnet" "private_c" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[2]
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 3)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-c"
  })
}

# DB subnet group spanning all three AZs so the cluster storage replicates
# across them.
resource "aws_db_subnet_group" "mysql_cluster" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Subnet group spanning three AZs for the MySQL Multi-AZ DB cluster."
  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
    aws_subnet.private_c.id,
  ]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

# -----------------------------------------------------------------------------
# Security
# -----------------------------------------------------------------------------

# Database security group: MySQL (3306) from the VPC CIDR only, no public access.
resource "aws_security_group" "mysql_cluster" {
  name        = "${local.name_prefix}-db-sg"
  description = "MySQL cluster access restricted to the dedicated VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL (3306) from within the VPC only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "MySQL (3306) responses within the VPC only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

# Customer-managed KMS key with automatic rotation for encryption at rest.
resource "aws_kms_key" "mysql_cluster" {
  description             = "CMK encrypting the MySQL Multi-AZ DB cluster storage and the master credentials secret."
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Master credentials (generated, stored in Secrets Manager, never hardcoded)
# -----------------------------------------------------------------------------

resource "random_password" "db_master_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>?"
}

resource "aws_secretsmanager_secret" "db_master_credentials" {
  name                    = "${local.name_prefix}-db-master-credentials"
  description             = "Master credentials for the MySQL Multi-AZ DB cluster."
  kms_key_id              = aws_kms_key.mysql_cluster.arn
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master_credentials" {
  secret_id = aws_secretsmanager_secret.db_master_credentials.id
  secret_string = jsonencode({
    username = var.db_master_username
    password = random_password.db_master_password.result
  })
}

# -----------------------------------------------------------------------------
# RDS MySQL Multi-AZ DB cluster
# -----------------------------------------------------------------------------

# A single 100 GiB io1 cluster volume is defined once at the cluster level and
# synchronously replicated across the three AZs; it is not 100 GB per instance
# or per AZ.
resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier     = "${local.name_prefix}-mysql-cluster"
  engine                 = "mysql"
  engine_version         = var.db_engine_version
  database_name          = "appdb"
  master_username        = var.db_master_username
  master_password        = random_password.db_master_password.result
  db_subnet_group_name   = aws_db_subnet_group.mysql_cluster.name
  vpc_security_group_ids = [aws_security_group.mysql_cluster.id]
  port                   = 3306

  storage_type      = "io1"
  allocated_storage = 100
  iops              = 3000

  storage_encrypted = true
  kms_key_id        = aws_kms_key.mysql_cluster.arn

  backup_retention_period = var.db_backup_retention_days
  preferred_backup_window = "03:00-04:00"
  copy_tags_to_snapshot   = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-mysql-cluster-final-snapshot"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# One DB instance per AZ; the first to join becomes the writer and the other two
# become readers, so the writer and readers span all three AZs.
resource "aws_rds_cluster_instance" "mysql_instance_1" {
  identifier                            = "${local.name_prefix}-instance-1"
  cluster_identifier                    = aws_rds_cluster.mysql_cluster.id
  instance_class                        = var.db_instance_class
  engine                                = "mysql"
  engine_version                        = var.db_engine_version
  availability_zone                     = data.aws_availability_zones.available.names[0]
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "mysql_instance_2" {
  identifier                            = "${local.name_prefix}-instance-2"
  cluster_identifier                    = aws_rds_cluster.mysql_cluster.id
  instance_class                        = var.db_instance_class
  engine                                = "mysql"
  engine_version                        = var.db_engine_version
  availability_zone                     = data.aws_availability_zones.available.names[1]
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-2"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "mysql_instance_3" {
  identifier                            = "${local.name_prefix}-instance-3"
  cluster_identifier                    = aws_rds_cluster.mysql_cluster.id
  instance_class                        = var.db_instance_class
  engine                                = "mysql"
  engine_version                        = var.db_engine_version
  availability_zone                     = data.aws_availability_zones.available.names[2]
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-3"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "writer_endpoint" {
  description = "Writer endpoint of the MySQL Multi-AZ DB cluster."
  value       = aws_rds_cluster.mysql_cluster.endpoint
}

output "reader_endpoint" {
  description = "Reader endpoint of the MySQL Multi-AZ DB cluster."
  value       = aws_rds_cluster.mysql_cluster.reader_endpoint
}

output "database_port" {
  description = "Port the MySQL cluster listens on."
  value       = aws_rds_cluster.mysql_cluster.port
}

output "db_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials."
  value       = aws_secretsmanager_secret.db_master_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Default provider: base table and primary KMS key are created here.
provider "aws" {
  region = "us-east-1"
}

# Additional provider configurations for the same AWS provider, required so
# the multi-region KMS replica keys can be created in the replica regions.
provider "aws" {
  alias  = "us_east_2"
  region = "us-east-2"
}

provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

variable "environment" {
  description = "Environment name applied as a consistent tag to all managed resources."
  type        = string
  default     = "production"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# Multi-region customer-managed KMS key (primary) used for encryption at rest.
resource "aws_kms_key" "dynamodb_global" {
  description             = "Multi-region customer-managed key for the DynamoDB global table (primary in us-east-1)"
  multi_region            = true
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Regional replica of the multi-region key for the us-east-2 table replica.
resource "aws_kms_replica_key" "dynamodb_us_east_2" {
  provider                = aws.us_east_2
  description             = "Multi-region customer-managed key replica for the DynamoDB global table (us-east-2)"
  primary_key_arn         = aws_kms_key.dynamodb_global.arn
  deletion_window_in_days = 30
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Regional replica of the multi-region key for the us-west-2 table replica.
resource "aws_kms_replica_key" "dynamodb_us_west_2" {
  provider                = aws.us_west_2
  description             = "Multi-region customer-managed key replica for the DynamoDB global table (us-west-2)"
  primary_key_arn         = aws_kms_key.dynamodb_global.arn
  deletion_window_in_days = 30
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# DynamoDB global table: base table in us-east-1 with replicas in us-east-2
# and us-west-2, streams enabled for replication, CMK encryption, PITR,
# and deletion protection.
resource "aws_dynamodb_table" "main" {
  name         = "global_table_main"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  # Streams are required for global table replication.
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  # Encryption at rest with the customer-managed multi-region key.
  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb_global.arn
  }

  # Point-in-time recovery protects all regional copies from accidental
  # writes and deletes.
  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  replica {
    region_name = "us-east-2"
    kms_key_arn = aws_kms_replica_key.dynamodb_us_east_2.arn
  }

  replica {
    region_name = "us-west-2"
    kms_key_arn = aws_kms_replica_key.dynamodb_us_west_2.arn
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  environment = "production"
  project     = "dax_cache"

  common_tags = {
    Environment = local.environment
    Project     = local.project
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "dax_vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "dax_private_subnet_${count.index + 1}"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "dax_private_route_table"
  })
}

# Note: aws_route_table_association is a pure linkage object with no tags
# support in the provider schema or the AWS API; network-layer tagging
# coverage is provided by aws_route_table.private and aws_subnet.private.
resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "dynamodb" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.dynamodb"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, {
    Name = "dax_dynamodb_gateway_endpoint"
  })
}

resource "aws_security_group" "dax" {
  name        = "dax_security_group"
  description = "DAX cluster security group - ingress limited to DAX endpoint port 8111, egress limited to HTTPS 443"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "DAX endpoint port (TCP 8111) from within the VPC"
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description     = "HTTPS (TCP 443) to DynamoDB via the gateway VPC endpoint"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [aws_vpc_endpoint.dynamodb.prefix_list_id]
  }

  tags = merge(local.common_tags, {
    Name = "dax_security_group"
  })
}

# Note: aws_dax_subnet_group does not support tags at the AWS API level;
# metadata is recorded via the schema-supported description argument instead.
resource "aws_dax_subnet_group" "main" {
  name        = "dax-subnet-group"
  description = "Managed by Terraform (${local.environment}) - private subnets hosting DAX cluster nodes"
  subnet_ids  = aws_subnet.private[*].id
}

resource "aws_dynamodb_table" "cache_table" {
  name         = "dax_cache_table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"

  attribute {
    name = "pk"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "dax_cache_table"
  })
}

resource "aws_iam_role" "dax" {
  name        = "dax_cluster_role"
  description = "IAM role assumed by the DAX cluster to access DynamoDB on behalf of clients"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# Note: IAM inline policies are not taggable; aws_iam_role_policy correctly omits tags.
resource "aws_iam_role_policy" "dax_dynamodb_access" {
  name = "dax_dynamodb_data_plane"
  role = aws_iam_role.dax.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DaxTableDataPlaneAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:BatchGetItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:ConditionCheckItem",
          "dynamodb:DescribeTable"
        ]
        Resource = [
          aws_dynamodb_table.cache_table.arn,
          "${aws_dynamodb_table.cache_table.arn}/index/*"
        ]
      }
    ]
  })
}

# Note: aws_dax_parameter_group does not support tags at the AWS API level;
# metadata is recorded via the schema-supported description argument instead.
resource "aws_dax_parameter_group" "main" {
  name        = "dax-parameter-group"
  description = "Managed by Terraform (${local.environment}) - DAX cache TTL parameters"

  parameters {
    name  = "query-ttl-millis"
    value = "60000"
  }

  parameters {
    name  = "record-ttl-millis"
    value = "300000"
  }
}

resource "aws_dax_cluster" "main" {
  cluster_name                     = "dax-cache-cluster"
  iam_role_arn                     = aws_iam_role.dax.arn
  node_type                        = "dax.r6g.large"
  replication_factor               = 3
  subnet_group_name                = aws_dax_subnet_group.main.name
  security_group_ids               = [aws_security_group.dax.id]
  parameter_group_name             = aws_dax_parameter_group.main.name
  cluster_endpoint_encryption_type = "TLS"

  server_side_encryption {
    enabled = true
  }

  depends_on = [aws_iam_role_policy.dax_dynamodb_access]

  tags = merge(local.common_tags, {
    Name = "dax-cache-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "dax_cluster_id" {
  description = "The ID of the DAX cluster."
  value       = aws_dax_cluster.main.id
}

output "dax_configuration_endpoint" {
  description = "The configuration endpoint (DNS name and port) of the DAX cluster."
  value       = aws_dax_cluster.main.configuration_endpoint
}

output "dax_iam_role_arn" {
  description = "The ARN of the IAM role assumed by the DAX cluster."
  value       = aws_iam_role.dax.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment label used solely for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  table_name         = "data-with-ttl"
  ttl_attribute_name = "expires_at"
}

resource "aws_dynamodb_table" "data_with_ttl" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  # Only the key-schema attribute is declared here. The TTL attribute
  # (expires_at) is intentionally NOT part of the schema per DynamoDB
  # TTL semantics.
  attribute {
    name = "id"
    type = "S"
  }

  ttl {
    enabled        = true
    attribute_name = local.ttl_attribute_name
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  tags = {
    Name        = local.table_name
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Demonstration item used to validate TTL expiration behavior.
# "expires_at" is stored as a DynamoDB Number (N) whose stringified value
# is the Unix epoch seconds timestamp 4102444800 (2100-01-01T00:00:00Z),
# a future time at which DynamoDB will automatically purge the item.
resource "aws_dynamodb_table_item" "sample" {
  table_name = aws_dynamodb_table.data_with_ttl.name
  hash_key   = aws_dynamodb_table.data_with_ttl.hash_key

  item = jsonencode({
    id = {
      S = "sample-record-001"
    }
    expires_at = {
      N = "4102444800"
    }
    payload = {
      S = "Demonstration record used to validate custom TTL expiration behavior."
    }
  })
}

output "table_name" {
  description = "Name of the DynamoDB table with custom TTL expiration enabled."
  value       = aws_dynamodb_table.data_with_ttl.name
}

output "ttl_attribute_name" {
  description = "Name of the DynamoDB attribute driving TTL expiration (Number type holding Unix epoch seconds)."
  value       = aws_dynamodb_table.data_with_ttl.ttl[0].attribute_name
}

