}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for cost allocation and ownership tracking tags."
  type        = string
  default     = "chime-voice-connector"

  validation {
    condition     = length(trimspace(var.project)) > 0
    error_message = "Project tag value must not be empty."
  }
}

variable "environment" {
  description = "Environment name used for cost allocation and ownership tracking tags."
  type        = string
  default     = "production"

  validation {
    condition     = length(trimspace(var.environment)) > 0
    error_message = "Environment tag value must not be empty."
  }
}

locals {
  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_chime_voice_connector" "main" {
  name               = "main-voice-connector"
  aws_region         = "us-east-1"
  require_encryption = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_chime_voice_connector_logging" "main" {
  voice_connector_id       = aws_chime_voice_connector.main.id
  enable_sip_logs          = false
  enable_media_metric_logs = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static, well-known metadata lookups (no pre-existing infrastructure required).
# Used to build the KMS key policy without hardcoding account IDs or partitions.
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  voice_connector_name  = "media_connector"
  media_stream_name     = "chime_media_stream"
  media_retention_hours = 24

  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Amazon Chime Voice Connector - anchor resource for live call traffic.
# require_encryption = true enforces TLS signaling and SRTP media, the correct
# security posture for call audio streamed to Kinesis Video Streams.
# -----------------------------------------------------------------------------
resource "aws_chime_voice_connector" "media_connector" {
  name               = local.voice_connector_name
  aws_region         = "us-east-1"
  require_encryption = true

  tags = merge(local.common_tags, {
    Name = local.voice_connector_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Enable SIP signaling logs and media metric logs for observability
# in CloudWatch Logs. Wired via the connector's `id` attribute, which holds
# the Voice Connector ID.
# -----------------------------------------------------------------------------
resource "aws_chime_voice_connector_logging" "media_connector_logging" {
  voice_connector_id       = aws_chime_voice_connector.media_connector.id
  enable_sip_logs          = true
  enable_media_metric_logs = true
}

# -----------------------------------------------------------------------------
# KMS key used for encryption at rest on the Kinesis Video Stream.
# The first statement enables IAM policy delegation for the owning account
# (required to administer the key); the second grants the Kinesis Video
# Streams service principal only the encryption actions it needs.
# -----------------------------------------------------------------------------
resource "aws_kms_key" "media_stream" {
  description             = "Encrypts Chime Voice Connector call media streamed to Kinesis Video Streams"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountIAMPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:Create*",
          "kms:Decrypt",
          "kms:Delete*",
          "kms:Describe*",
          "kms:Disable*",
          "kms:Enable*",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:Get*",
          "kms:List*",
          "kms:Put*",
          "kms:ReEncrypt*",
          "kms:RetireGrant",
          "kms:Revoke*",
          "kms:ScheduleKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:Update*"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowKinesisVideoStreamsServiceEncryption"
        Effect = "Allow"
        Principal = {
          Service = "kinesisvideo.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "chime-media-stream-key"
  })
}

resource "aws_kms_alias" "media_stream" {
  name          = "alias/chime-media-stream"
  target_key_id = aws_kms_key.media_stream.key_id
}

# -----------------------------------------------------------------------------
# Kinesis Video Stream that receives the streamed Voice Connector call audio.
# Its data retention period must match the Voice Connector streaming
# configuration retention period.
# -----------------------------------------------------------------------------
resource "aws_kinesis_video_stream" "media_stream" {
  name                    = local.media_stream_name
  data_retention_in_hours = local.media_retention_hours
  kms_key_id              = aws_kms_key.media_stream.arn

  tags = merge(local.common_tags, {
    Name = local.media_stream_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Streaming configuration: sends Voice Connector call audio to the Kinesis
# Video Stream. Retention matches the stream; streaming is enabled.
# -----------------------------------------------------------------------------
resource "aws_chime_voice_connector_streaming" "media_connector_streaming" {
  voice_connector_id = aws_chime_voice_connector.media_connector.id
  data_retention     = local.media_retention_hours
  disabled           = false

  depends_on = [aws_kinesis_video_stream.media_stream]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "default_tags" {
  description = "Default tags applied to every taggable resource in this configuration."
  type        = map(string)
  default = {
    Project     = "redshift-event-notifications"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  cluster_identifier        = "redshift-events-cluster"
  database_name             = "eventsdb"
  master_username           = "redshiftadmin"
  final_snapshot_identifier = "${local.cluster_identifier}-final-snapshot"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.default_tags, { Name = "redshift-events-vpc" })
}

resource "aws_subnet" "redshift_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(var.default_tags, { Name = "redshift-events-subnet-a" })
}

resource "aws_subnet" "redshift_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(var.default_tags, { Name = "redshift-events-subnet-b" })
}

resource "aws_redshift_subnet_group" "redshift" {
  name        = "redshift-events-subnet-group"
  description = "Subnet group for the Redshift events cluster spanning multiple availability zones"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = var.default_tags
}

resource "aws_security_group" "redshift" {
  name        = "redshift-events-sg"
  description = "Restricts ingress to the Redshift engine port (5439) from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(var.default_tags, { Name = "redshift-events-sg" })
}

# ---------------------------------------------------------------------------
# Encryption
# ---------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Encrypts the Redshift cluster, the SNS event topic, and the master password secret"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = var.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/redshift-events-key"
  target_key_id = aws_kms_key.redshift.key_id
}

# ---------------------------------------------------------------------------
# Master credentials (runtime-generated, persisted in Secrets Manager)
# ---------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name                    = "redshift-events-cluster-master-password"
  description             = "Master password for the ${local.cluster_identifier} Redshift cluster"
  kms_key_id              = aws_kms_key.redshift.arn
  recovery_window_in_days = 7

  tags = var.default_tags
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id     = aws_secretsmanager_secret.redshift_master.id
  secret_string = random_password.redshift_master.result
}

# ---------------------------------------------------------------------------
# Event delivery topic
# ---------------------------------------------------------------------------

resource "aws_sns_topic" "redshift_events" {
  name              = "redshift-cluster-events"
  kms_master_key_id = aws_kms_key.redshift.arn

  tags = var.default_tags
}

data "aws_iam_policy_document" "redshift_events_topic" {
  policy_id = "RedshiftEventsTopicPolicy"

  statement {
    sid       = "AllowRedshiftEventPublishing"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.redshift_events.arn]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = data.aws_iam_policy_document.redshift_events_topic.json
}

# ---------------------------------------------------------------------------
# Redshift cluster
# ---------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier = local.cluster_identifier
  database_name      = local.database_name
  cluster_type       = "single-node"
  node_type          = "dc2.large"
  master_username    = local.master_username
  master_password    = aws_secretsmanager_secret_version.redshift_master.secret_string

  cluster_subnet_group_name = aws_redshift_subnet_group.redshift.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = false
  port                      = 5439

  encrypted  = true
  kms_key_id = aws_kms_key.redshift.arn

  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = local.final_snapshot_identifier

  tags = merge(var.default_tags, { Name = local.cluster_identifier })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Event subscription (cluster lifecycle events -> SNS)
# ---------------------------------------------------------------------------

resource "aws_redshift_event_subscription" "cluster_events" {
  name             = "redshift-cluster-events-subscription"
  sns_topic_arn    = aws_sns_topic.redshift_events.arn
  source_type      = "cluster"
  source_ids       = [aws_redshift_cluster.main.cluster_identifier]
  severity         = "INFO"
  event_categories = ["management"]
  enabled          = true

  tags = var.default_tags

  depends_on = [aws_sns_topic_policy.redshift_events]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_group" "example" {
  name = "example_group"
  path = "/"
}

resource "aws_iam_policy" "example" {
  name        = "example_group_policy"
  path        = "/"
  description = "Least-privilege policy allowing members of the example group to inspect the group itself and its attached policies"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GroupSelfInspection"
        Effect = "Allow"
        Action = [
          "iam:GetGroup",
          "iam:GetGroupPolicy",
          "iam:ListAttachedGroupPolicies",
          "iam:ListGroupPolicies"
        ]
        Resource = aws_iam_group.example.arn
      }
    ]
  })

  tags = {
    Name        = "example_group_policy"
    Environment = "example"
  }
}

resource "aws_iam_group_policy_attachment" "example" {
  group      = aws_iam_group.example.name
  policy_arn = aws_iam_policy.example.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "virtual_mfa_device_name" {
  description = "Descriptive name for the IAM virtual MFA device."
  type        = string
  default     = "basic-virtual-mfa-device"
}

resource "aws_iam_virtual_mfa_device" "base" {
  virtual_mfa_device_name = var.virtual_mfa_device_name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "mybucket" {
  bucket = "mybucket"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "mybucket" {
  bucket = aws_s3_bucket.mybucket.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "mybucket" {
  bucket = aws_s3_bucket.mybucket.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.mybucket]
}

resource "aws_s3_bucket_public_access_block" "mybucket" {
  bucket = aws_s3_bucket.mybucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "mybucket" {
  bucket = aws_s3_bucket.mybucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

variable "bucket_name_suffix" {
  description = "Globally unique suffix used to construct the S3 bucket names. Change this to any lowercase value unique to your account and Region."
  type        = string
  default     = "cfg-inventory-001"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$", var.bucket_name_suffix))
    error_message = "The suffix must be 3-40 characters of lowercase letters, numbers, and hyphens so the resulting bucket names are valid S3 bucket names."
  }
}

locals {
  source_bucket_name    = "inventory-source-${var.bucket_name_suffix}"
  inventory_bucket_name = "inventory-reports-${var.bucket_name_suffix}"
  inventory_prefix      = "weekly-inventory"

  common_tags = {
    ManagedBy   = "terraform"
    Purpose     = "weekly-csv-object-inventory"
    Environment = "production"
  }
}

# ---------------------------------------------------------------------------
# Source bucket: holds the objects whose current versions are inventoried
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "source" {
  bucket = local.source_bucket_name

  tags = merge(
    local.common_tags,
    {
      Name = local.source_bucket_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "source" {
  bucket = aws_s3_bucket.source.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source" {
  bucket = aws_s3_bucket.source.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "source" {
  bucket = aws_s3_bucket.source.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "source" {
  bucket = aws_s3_bucket.source.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# ---------------------------------------------------------------------------
# Destination bucket: stores the weekly CSV inventory reports
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "inventory_dest" {
  bucket = local.inventory_bucket_name

  tags = merge(
    local.common_tags,
    {
      Name = local.inventory_bucket_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "inventory_dest" {
  bucket = aws_s3_bucket.inventory_dest.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "inventory_dest" {
  bucket = aws_s3_bucket.inventory_dest.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "inventory_dest" {
  bucket = aws_s3_bucket.inventory_dest.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "inventory_dest" {
  bucket = aws_s3_bucket.inventory_dest.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# ---------------------------------------------------------------------------
# Destination bucket policy: allows only the S3 inventory delivery from the
# source bucket to write report objects (s3:PutObject only, least-privilege)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "inventory_dest" {
  bucket = aws_s3_bucket.inventory_dest.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3InventoryDelivery"
        Effect    = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.inventory_dest.arn}/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.source.arn
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.inventory_dest]
}

# ---------------------------------------------------------------------------
# Weekly CSV inventory of current object versions in the source bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_inventory" "source_weekly_current_csv" {
  bucket = aws_s3_bucket.source.id
  name   = "weekly_current_versions_csv"

  included_object_versions = "Current"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.inventory_dest.arn
      format     = "CSV"
      prefix     = local.inventory_prefix
    }
  }

  optional_fields = ["Size", "LastModifiedDate", "StorageClass", "EncryptionStatus"]

  depends_on = [aws_s3_bucket_policy.inventory_dest]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "source_bucket_name" {
  description = "Name of the S3 bucket whose current object versions are inventoried."
  value       = aws_s3_bucket.source.id
}

output "inventory_destination_uri" {
  description = "S3 URI prefix where the weekly CSV inventory reports are delivered."
  value       = "s3://${aws_s3_bucket.inventory_dest.id}/${local.inventory_prefix}"
}

output "inventory_report_name" {
  description = "Name of the S3 inventory configuration generating the weekly CSV report."
  value       = aws_s3_bucket_inventory.source_weekly_current_csv.name
}

