}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "User-controlled, globally unique name for the PDF storage bucket (must be lowercase, 3-63 chars)"
  type        = string
  default     = "pdf-storage-assets-bucket"
}

variable "environment" {
  description = "Environment tag applied to all resources"
  type        = string
  default     = "dev"
}

variable "project" {
  description = "Project tag applied to all resources"
  type        = string
  default     = "pdf-storage"
}

locals {
  bucket_name = lower(var.bucket_name)
  common_tags = {
    Environment = var.environment
    Project     = var.project
    ManagedBy   = "terraform"
  }
}

resource "aws_s3_bucket" "pdf_storage" {
  bucket = local.bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "pdf_storage" {
  bucket = aws_s3_bucket.pdf_storage.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "pdf_storage" {
  bucket = aws_s3_bucket.pdf_storage.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "pdf_storage" {
  bucket = aws_s3_bucket.pdf_storage.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "pdf_storage" {
  bucket = aws_s3_bucket.pdf_storage.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "pdf_storage" {
  bucket = aws_s3_bucket.pdf_storage.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.pdf_storage.arn,
          "${aws_s3_bucket.pdf_storage.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.pdf_storage]
}

resource "aws_s3_object" "pdf_upload" {
  bucket       = aws_s3_bucket.pdf_storage.id
  key          = "test.pdf"
  source       = "assets/test.pdf"
  content_type = "application/pdf"

  tags = local.common_tags

  depends_on = [
    aws_s3_bucket_ownership_controls.pdf_storage,
    aws_s3_bucket_server_side_encryption_configuration.pdf_storage,
    aws_s3_bucket_versioning.pdf_storage,
    aws_s3_bucket_policy.pdf_storage
  ]
}

